/**
 * Carries EditorSelectionTestHarness state used by the test layer.
 */
struct EditorSelectionTestHarness {
  explicit EditorSelectionTestHarness(SceneDocument &scene,
                                      AssetRegistry &assets,
                                      ModelingSessionService &modeling)
      : document_commands(scene, history),
        selection(scene, document_commands, modeling) {
    (void)assets;
  }

  EditorHistoryService history;
  DocumentCommandService document_commands;
  EditorSelectionService selection;
};

DocumentCommandResult
select_through_editor(EditorSelectionService &selection,
                      std::initializer_list<EntityId> entities,
                      EntityId active = kInvalidEntityId) {
  std::vector<EntityId> selected(entities);
  const EntityId resolved_active =
      active != kInvalidEntityId || selected.empty() ? active : selected.back();
  return selection.set_scene_selection(
      std::span<const EntityId>(selected.data(), selected.size()),
      resolved_active);
}

ModelingCommandResult seed_component_bulk_selection_scope(
    ModelingSessionService &service, int modeling_object_id,
    ModelingSelectionMode mode,
    ModelingSelectionEdit edit = ModelingSelectionEdit::Add) {
  ModelingComponentSelectionRequest request{
      .modeling_object_id = modeling_object_id,
      .mode = mode,
      .edit = edit,
  };
  switch (mode) {
  case ModelingSelectionMode::Vertex:
    request.vertices = {1};
    request.active_kind = ModelingActiveSelectionKind::Vertex;
    request.active_vertex = 1;
    break;
  case ModelingSelectionMode::Edge:
    request.edges = {{1, 2}};
    request.active_kind = ModelingActiveSelectionKind::Edge;
    request.active_edge = {1, 2};
    break;
  case ModelingSelectionMode::Face:
    request.faces = {1};
    request.active_kind = ModelingActiveSelectionKind::Face;
    request.active_face = 1;
    break;
  case ModelingSelectionMode::Object:
  case ModelingSelectionMode::Group:
    return {.ok = false,
            .changed = false,
            .message = "A component mode is required."};
  }
  return service.set_component_selection(request);
}

