TEST(LoggerTests, RoutesMessagesToMemorySink) {
  Logger::initialize(
      LoggerConfig{.name = "test", .file_path = "test.log", .max_entries = 16});
  Logger::clear_memory();

  LOG_INFO("hello {}", "quader");

  const auto entries = Logger::entries_snapshot();
  ASSERT_FALSE(entries.empty());
  EXPECT_NE(entries.back().message.find("hello quader"), std::string::npos);
}

TEST(LoggerTests, MemoryRevisionChangesOnlyWhenMemoryContentsCanChange) {
  Logger::initialize(LoggerConfig{.name = "revision-test",
                                  .file_path = "",
                                  .max_entries = 16});
  const std::uint64_t initialized = Logger::memory_revision();
  (void)Logger::entries_snapshot();
  EXPECT_EQ(Logger::memory_revision(), initialized)
      << "read-only snapshots must keep the cheap UI gate stable";

  LOG_INFO("revision entry");
  const std::uint64_t logged = Logger::memory_revision();
  EXPECT_GT(logged, initialized);
  (void)Logger::entries_snapshot();
  EXPECT_EQ(Logger::memory_revision(), logged);

  Logger::clear_memory();
  EXPECT_GT(Logger::memory_revision(), logged);
}

TEST(LoggerTests, IncrementalMemoryCursorReturnsOnlyNewRingEntries) {
  Logger::initialize(LoggerConfig{.name = "incremental-memory-test",
                                  .file_path = "",
                                  .max_entries = 3});
  Logger::clear_memory();

  const LogEntriesDelta cleared = Logger::entries_since({});
  EXPECT_TRUE(cleared.reset_required);
  EXPECT_TRUE(cleared.entries.empty());

  LOG_INFO("incremental one");
  LOG_INFO("incremental two");
  const LogEntriesDelta first = Logger::entries_since(cleared.cursor);
  ASSERT_FALSE(first.reset_required);
  ASSERT_EQ(first.entries.size(), 2u);
  EXPECT_LT(first.entries[0].sequence, first.entries[1].sequence);

  LOG_INFO("incremental three");
  LOG_INFO("incremental four");
  const LogEntriesDelta ring_shift = Logger::entries_since(first.cursor);
  ASSERT_FALSE(ring_shift.reset_required);
  ASSERT_EQ(ring_shift.entries.size(), 2u);
  EXPECT_GT(ring_shift.first_sequence, first.entries.front().sequence);
  EXPECT_EQ(ring_shift.entries.front().sequence,
            first.entries.back().sequence + 1u);

  for (int index = 0; index < 6; ++index) {
    LOG_INFO("incremental skipped {}", index);
  }
  const LogEntriesDelta missed_ring = Logger::entries_since(ring_shift.cursor);
  EXPECT_TRUE(missed_ring.reset_required);
  EXPECT_EQ(missed_ring.entries.size(), 3u);
  EXPECT_EQ(missed_ring.first_sequence,
            missed_ring.entries.front().sequence);
}

TEST(LoggerTests, ConcurrentLifecycleAndSnapshotsKeepOwnedStateAlive) {
  const LoggerConfig config{
      .name = "logger-concurrency-test",
      .file_path = "",
      .max_entries = 64,
  };
  Logger::initialize(config);

  std::atomic_bool start = false;
  std::atomic_int acquisition_failures = 0;
  std::vector<std::thread> workers;
  workers.reserve(4u);
  for (int worker = 0; worker < 4; ++worker) {
    workers.emplace_back([worker, &start, &acquisition_failures]() {
      while (!start.load(std::memory_order_acquire)) {
        std::this_thread::yield();
      }
      for (int iteration = 0; iteration < 128; ++iteration) {
        const std::shared_ptr<spdlog::logger> logger = Logger::instance();
        if (!logger) {
          acquisition_failures.fetch_add(1, std::memory_order_relaxed);
          continue;
        }
        logger->info("worker {} iteration {}", worker, iteration);
        (void)Logger::entries_snapshot();
        if (iteration % 17 == 0) {
          Logger::clear_memory();
        }
      }
    });
  }
  std::thread lifecycle([&start, &config]() {
    while (!start.load(std::memory_order_acquire)) {
      std::this_thread::yield();
    }
    for (int iteration = 0; iteration < 32; ++iteration) {
      Logger::shutdown();
      Logger::initialize(config);
    }
  });

  start.store(true, std::memory_order_release);
  for (std::thread &worker : workers) {
    worker.join();
  }
  lifecycle.join();

  EXPECT_EQ(acquisition_failures.load(std::memory_order_relaxed), 0);
  Logger::initialize(config);
  Logger::clear_memory();
  LOG_INFO("logger remains usable after concurrent lifecycle changes");
  const std::vector<LogEntry> entries = Logger::entries_snapshot();
  ASSERT_FALSE(entries.empty());
  EXPECT_NE(entries.back().message.find("logger remains usable"),
            std::string::npos);
}

