TEST(ConsoleModelTests, FiltersByLevelAndSearch) {
  std::vector<LogEntry> entries = {
      {.level = spdlog::level::info, .message = "engine ready"},
      {.level = spdlog::level::err, .message = "vulkan failed"},
  };

  const auto filtered = ConsoleModel::filter(
      entries, {.level_mask = kConsoleErrorLevel, .search_text = "VULKAN"});

  ASSERT_EQ(filtered.size(), 1u);
  EXPECT_EQ(filtered[0].message, "vulkan failed");
}

TEST(ConsoleModelTests, SelectsExactCategoriesAndGroupsCriticalWithError) {
  std::vector<LogEntry> entries = {
      {.level = spdlog::level::trace, .message = "trace"},
      {.level = spdlog::level::debug, .message = "debug"},
      {.level = spdlog::level::info, .message = "info"},
      {.level = spdlog::level::warn, .message = "warn"},
      {.level = spdlog::level::err, .message = "error"},
      {.level = spdlog::level::critical, .message = "critical"},
      {.level = spdlog::level::off, .message = "off"},
  };

  EXPECT_EQ(
      ConsoleModel::filter(entries, {})
          .size(),
      6u);
  EXPECT_EQ(
      ConsoleModel::filter(entries, {.level_mask = kConsoleInfoLevel})
          .size(),
      1u);
  EXPECT_EQ(
      ConsoleModel::filter(entries, {.level_mask = kConsoleWarningLevel})
          .size(),
      1u);
  EXPECT_EQ(ConsoleModel::filter(entries, {.level_mask = kConsoleErrorLevel})
                .size(),
            2u);
  EXPECT_TRUE(
      ConsoleModel::filter(entries, {.level_mask = 0u})
          .empty());
  const auto mixed = ConsoleModel::filter(
      entries, {.level_mask = kConsoleTraceLevel | kConsoleWarningLevel});
  ASSERT_EQ(mixed.size(), 2u);
  EXPECT_EQ(mixed[0].message, "trace");
  EXPECT_EQ(mixed[1].message, "warn");
}

TEST(ConsoleModelTests, KeepsStructuredPayloadSeparateFromFormattedCompatibilityText) {
  Logger::initialize({.name = "console-structured-test", .file_path = ""});
  LOG_WARN("first line\nsecond line");
  const auto entries = Logger::entries_snapshot();
  ASSERT_EQ(entries.size(), 1u);
  EXPECT_EQ(entries[0].payload, "first line\nsecond line");
  EXPECT_NE(entries[0].timestamp, spdlog::log_clock::time_point{});
  ASSERT_GT(entries[0].message.size(), 13u);
  EXPECT_EQ(entries[0].message[9], '.');
  EXPECT_NE(entries[0].message.find("[warning]"), std::string::npos);
  EXPECT_NE(entries[0].message.find(entries[0].payload), std::string::npos);
}

TEST(AppWindowSettingsTests, RoundTripsNormalBoundsAndMaximizedState) {
  const std::filesystem::path path = std::filesystem::temp_directory_path() /
                                     "quader_window_settings_round_trip.ini";
  std::filesystem::remove(path);

  AppWindowSettings settings = AppWindowSettings::defaults();
  settings.set_placement({
      .normal_frame =
          {
              .x = -120,
              .y = 84,
              .width = 1440,
              .height = 900,
          },
      .maximized = true,
  });

  ASSERT_TRUE(settings.save(path));
  const AppWindowSettings loaded = AppWindowSettings::load(path);

  ASSERT_TRUE(loaded.placement().has_value());
  EXPECT_EQ(loaded.placement()->normal_frame.x, -120);
  EXPECT_EQ(loaded.placement()->normal_frame.y, 84);
  EXPECT_EQ(loaded.placement()->normal_frame.width, 1440);
  EXPECT_EQ(loaded.placement()->normal_frame.height, 900);
  EXPECT_TRUE(loaded.placement()->maximized);
}

TEST(AppWindowSettingsTests, IgnoresIncompleteWindowPlacementFiles) {
  const std::filesystem::path path = std::filesystem::temp_directory_path() /
                                     "quader_window_settings_incomplete.ini";
  std::filesystem::remove(path);

  {
    std::ofstream file(path, std::ios::trunc);
    ASSERT_TRUE(file.is_open());
    file << "[Window]\n";
    file << "NormalX=10\n";
    file << "NormalY=20\n";
    file << "Maximized=true\n";
  }

  const AppWindowSettings loaded = AppWindowSettings::load(path);
  EXPECT_FALSE(loaded.placement().has_value());
}

TEST(AppFrameScheduleTests, PreservesSynchronizedAndIdleCadence) {
  AppFrameSchedule schedule;
  EXPECT_EQ(schedule.next_interval_ms(true, true, 17, true), 17);
  EXPECT_EQ(schedule.next_interval_ms(true, true, 6, true), 6);
  EXPECT_EQ(schedule.next_interval_ms(true, true, 17, false), 17);
  EXPECT_EQ(schedule.next_interval_ms(false, false, 0, true), 16);
}

TEST(AppFrameScheduleTests, UncappedFramesYieldWhenRendererCannotProgress) {
  AppFrameSchedule schedule;
  EXPECT_EQ(schedule.next_interval_ms(true, false, 0, true), 0);
  EXPECT_EQ(schedule.next_interval_ms(true, false, 0, false), 1);
  EXPECT_EQ(schedule.next_interval_ms(true, false, 0, false), 2);
  for (int attempt = 0; attempt < 10; ++attempt) {
    EXPECT_EQ(schedule.next_interval_ms(true, false, 0, false), 4);
  }
  EXPECT_EQ(schedule.next_interval_ms(true, false, 0, true), 0);
  EXPECT_EQ(schedule.next_interval_ms(true, false, 0, false), 1);
}

TEST(AppFrameScheduleTests, FallbackAndIdleClearBackoffForNextActivation) {
  AppFrameSchedule schedule;
  for (int attempt = 0; attempt < 4; ++attempt) {
    (void)schedule.next_interval_ms(true, false, 0, false);
  }
  EXPECT_EQ(schedule.next_interval_ms(true, true, 17, false), 17);
  EXPECT_EQ(schedule.next_interval_ms(true, false, 0, false), 1);
  EXPECT_EQ(schedule.next_interval_ms(false, false, 0, false), 16);
  EXPECT_EQ(schedule.next_interval_ms(true, false, 0, false), 1);
}

