TEST(UISettingsTests, ClampsFiniteInterfaceScaleAndRejectsNonFiniteValues) {
  const std::filesystem::path low_path =
      std::filesystem::temp_directory_path() /
      "quader_ui_settings_low_interface_scale.ini";
  const std::filesystem::path high_path =
      std::filesystem::temp_directory_path() /
      "quader_ui_settings_high_interface_scale.ini";
  const std::filesystem::path non_finite_path =
      std::filesystem::temp_directory_path() /
      "quader_ui_settings_non_finite_interface_scale.ini";

  const auto write_scale = [](const std::filesystem::path &path,
                              std::string_view value) {
    std::ofstream file(path, std::ios::trunc);
    ASSERT_TRUE(file.is_open());
    file << "[Interface]\nInterfaceScale=" << value << '\n';
  };
  write_scale(low_path, "0.25");
  write_scale(high_path, "4.5");
  write_scale(non_finite_path, "inf");

  EXPECT_FLOAT_EQ(UISettings::load(low_path).interface_scale(),
                  UISettings::kMinimumInterfaceScale);
  EXPECT_FLOAT_EQ(UISettings::load(high_path).interface_scale(),
                  UISettings::kMaximumInterfaceScale);
  EXPECT_FLOAT_EQ(UISettings::load(non_finite_path).interface_scale(),
                  UISettings::kDefaultInterfaceScale);

  UISettings settings = UISettings::defaults();
  settings.set_interface_scale(-10.0F);
  EXPECT_FLOAT_EQ(settings.interface_scale(),
                  UISettings::kMinimumInterfaceScale);
  settings.set_interface_scale(10.0F);
  EXPECT_FLOAT_EQ(settings.interface_scale(),
                  UISettings::kMaximumInterfaceScale);
  settings.set_interface_scale(std::numeric_limits<float>::quiet_NaN());
  EXPECT_FLOAT_EQ(settings.interface_scale(),
                  UISettings::kDefaultInterfaceScale);

  std::filesystem::remove(low_path);
  std::filesystem::remove(high_path);
  std::filesystem::remove(non_finite_path);
}

TEST(WindowPlacementTests, RecoversPersistedFrameToAVisibleWorkArea) {
  const std::vector<PlatformWindowChromeFrame> work_areas = {
      {.x = 0, .y = 0, .width = 1920, .height = 1040},
      {.x = -1280, .y = 0, .width = 1280, .height = 984},
  };

  const PlatformWindowChromeFrame offscreen =
      platform_window_recover_frame_to_display_work_area(
          {.x = 4000, .y = 2000, .width = 1600, .height = 900}, work_areas);
  EXPECT_EQ(offscreen.x, 320);
  EXPECT_EQ(offscreen.y, 140);
  EXPECT_EQ(offscreen.width, 1600);
  EXPECT_EQ(offscreen.height, 900);

  const PlatformWindowChromeFrame secondary =
      platform_window_recover_frame_to_display_work_area(
          {.x = -1200, .y = 100, .width = 900, .height = 700}, work_areas);
  EXPECT_EQ(secondary.x, -1200);
  EXPECT_EQ(secondary.y, 100);

  const PlatformWindowChromeFrame oversized =
      platform_window_recover_frame_to_display_work_area(
          {.x = 0, .y = 0, .width = 5000, .height = 3000}, work_areas);
  EXPECT_EQ(oversized.x, 0);
  EXPECT_EQ(oversized.y, 0);
  EXPECT_EQ(oversized.width, 1920);
  EXPECT_EQ(oversized.height, 1040);
}

TEST(WindowPlacementTests, PreservesMinimumSizeWithoutConnectedWorkAreas) {
  const PlatformWindowChromeFrame recovered =
      platform_window_recover_frame_to_display_work_area(
          {.x = 20, .y = 30, .width = 10, .height = 10},
          std::span<const PlatformWindowChromeFrame>{});
  EXPECT_EQ(recovered.x, 20);
  EXPECT_EQ(recovered.y, 30);
  EXPECT_EQ(recovered.width, kPlatformWindowMinimumWidth);
  EXPECT_EQ(recovered.height, kPlatformWindowMinimumHeight);
}

TEST(WindowPlacementTests, RecoversDecoratedFrameInsideSecondaryWorkArea) {
  const std::array work_areas{
      PlatformWindowChromeFrame{0, 0, 2560, 1440},
      PlatformWindowChromeFrame{2560, 486, 1920, 1032},
  };
  const PlatformWindowFrameMargins margins{
      .left = 8, .top = 31, .right = 8, .bottom = 8};
  const PlatformWindowChromeFrame recovered =
      platform_window_recover_frame_to_display_work_area(
          {.x = 2560, .y = 486, .width = 1920, .height = 1032}, work_areas,
          margins);
  EXPECT_EQ(recovered.x, 2568);
  EXPECT_EQ(recovered.y, 517);
  EXPECT_EQ(recovered.width, 1904);
  EXPECT_EQ(recovered.height, 993);

  const auto &secondary = work_areas[1];
  EXPECT_GE(recovered.x - margins.left, secondary.x);
  EXPECT_GE(recovered.y - margins.top, secondary.y);
  EXPECT_LE(recovered.x + recovered.width + margins.right,
            secondary.x + secondary.width);
  EXPECT_LE(recovered.y + recovered.height + margins.bottom,
            secondary.y + secondary.height);
}

TEST(WindowPlacementTests, MarginAwareRecoveryPreservesSafeFramesWithoutDrift) {
  const std::array work_areas{
      PlatformWindowChromeFrame{2560, 486, 1920, 1032},
  };
  const PlatformWindowFrameMargins margins{
      .left = 8, .top = 31, .right = 8, .bottom = 8};
  for (const auto original : std::array{
           PlatformWindowChromeFrame{2700, 600, 1600, 800},
           PlatformWindowChromeFrame{2568, 517, 1904, 993},
       }) {
    SCOPED_TRACE(original.x);
    PlatformWindowChromeFrame recovered = original;
    for (int restore = 0; restore < 3; ++restore) {
      SCOPED_TRACE(restore);
      recovered = platform_window_recover_frame_to_display_work_area(
          recovered, work_areas, margins);
      EXPECT_EQ(recovered.x, original.x);
      EXPECT_EQ(recovered.y, original.y);
      EXPECT_EQ(recovered.width, original.width);
      EXPECT_EQ(recovered.height, original.height);
    }
  }
}

