TEST(ViewportCameraAdapterTests,
     BuildsOverlayAndModelingCamerasFromSharedBasis) {
  ViewportCameraController camera;
  camera.set_clip_planes(0.01f, 250.0f);
  const ViewportOverlayCamera overlay =
      ViewportCameraAdapter::overlay_camera(camera, {0.0f, 240.0f});
  const ModelingViewportCamera modeling =
      ViewportCameraAdapter::modeling_camera(camera, {640.0f, 360.0f});

  EXPECT_EQ(overlay.projection, ViewportOverlayProjection::Perspective);
  EXPECT_FALSE(modeling.orthographic);
  EXPECT_FLOAT_EQ(overlay.viewport_size.x, 1.0f);
  EXPECT_FLOAT_EQ(overlay.viewport_size.y, 240.0f);
  EXPECT_FLOAT_EQ(overlay.near_plane, 0.01f);
  EXPECT_FLOAT_EQ(overlay.far_plane, 250.0f);
  expect_vec3_near(modeling.origin, overlay.eye);
  expect_vec3_near(modeling.x_axis, overlay.right);
  expect_vec3_near(modeling.y_axis, overlay.up);
  expect_vec3_near(modeling.z_axis, overlay.forward * -1.0f);
  EXPECT_NEAR(length(overlay.forward), 1.0f, 0.001f);
  EXPECT_NEAR(length(overlay.right), 1.0f, 0.001f);
  EXPECT_NEAR(length(overlay.up), 1.0f, 0.001f);
}

TEST(ViewportGridPlacementPolicyTests,
     ResolvesPerspectiveAndOrthographicPlanesWithoutFilament) {
  ViewportCameraController camera;
  camera.set_viewport_size(200.0f, 100.0f);

  const ViewportGridPlacement perspective =
      ViewportGridPlacementPolicy::placement(camera, 200u, 100u);
  EXPECT_EQ(perspective.plane, ViewportGridPlane::XZ);
  EXPECT_EQ(perspective.rotation, ViewportGridRotation::Identity);
  expect_vec3_near(perspective.origin, {});
  EXPECT_FLOAT_EQ(perspective.plane_size.x, 1024.0f);
  EXPECT_FLOAT_EQ(perspective.plane_size.y, 1024.0f);
  expect_vec3_near(perspective.axes.u_axis, {1.0f, 0.0f, 0.0f});
  expect_vec3_near(perspective.axes.v_axis, {0.0f, 0.0f, -1.0f});
  EXPECT_EQ(perspective.axes.u_color, ViewportColorSettingId::GridXAxis);
  EXPECT_EQ(perspective.axes.v_color, ViewportColorSettingId::GridZAxis);

  ViewportCameraPose translated_pose = camera.pose();
  const QVec3 camera_translation{123.0f, -45.0f, 678.0f};
  translated_pose.eye = translated_pose.eye + camera_translation;
  translated_pose.target = translated_pose.target + camera_translation;
  ASSERT_TRUE(camera.restore_perspective_pose(translated_pose));
  const ViewportGridPlacement translated_perspective =
      ViewportGridPlacementPolicy::placement(camera, 200u, 100u);
  expect_vec3_near(translated_perspective.origin, {});
  EXPECT_FLOAT_EQ(translated_perspective.plane_size.x, 1024.0f);
  EXPECT_FLOAT_EQ(translated_perspective.plane_size.y, 1024.0f);

  camera.view_axis(ViewportViewAxis::X, 1);
  const ViewportGridPlacement side =
      ViewportGridPlacementPolicy::placement(camera, 200u, 100u);
  const float ortho_plane_height =
      camera.state().orthographic_size * kViewportGridOrthographicMargin;
  EXPECT_EQ(side.plane, ViewportGridPlane::YZ);
  EXPECT_EQ(side.rotation, ViewportGridRotation::NegativeHalfPiAroundZ);
  EXPECT_FLOAT_EQ(side.origin.x, kViewportGridPlaneOffset);
  EXPECT_FLOAT_EQ(side.origin.y, camera.pose().eye.y);
  EXPECT_FLOAT_EQ(side.origin.z, camera.pose().eye.z);
  EXPECT_FLOAT_EQ(side.plane_size.x, ortho_plane_height);
  EXPECT_FLOAT_EQ(side.plane_size.y, ortho_plane_height * 2.0f);
  expect_vec3_near(side.axes.u_axis, {0.0f, 0.0f, -1.0f});
  expect_vec3_near(side.axes.v_axis, {0.0f, 1.0f, 0.0f});
  EXPECT_EQ(side.axes.u_color, ViewportColorSettingId::GridZAxis);
  EXPECT_EQ(side.axes.v_color, ViewportColorSettingId::GridYAxis);

  camera.view_axis(ViewportViewAxis::Z, 1);
  const ViewportGridPlacement front =
      ViewportGridPlacementPolicy::placement(camera, 200u, 100u);
  EXPECT_EQ(front.plane, ViewportGridPlane::XY);
  EXPECT_EQ(front.rotation, ViewportGridRotation::PositiveHalfPiAroundX);
  EXPECT_FLOAT_EQ(front.origin.x, camera.pose().eye.x);
  EXPECT_FLOAT_EQ(front.origin.y, camera.pose().eye.y);
  EXPECT_FLOAT_EQ(front.origin.z, kViewportGridPlaneOffset);
  EXPECT_FLOAT_EQ(front.plane_size.x, camera.state().orthographic_size *
                                          kViewportGridOrthographicMargin *
                                          2.0f);
  EXPECT_FLOAT_EQ(front.plane_size.y, camera.state().orthographic_size *
                                          kViewportGridOrthographicMargin);
  expect_vec3_near(front.axes.u_axis, {1.0f, 0.0f, 0.0f});
  expect_vec3_near(front.axes.v_axis, {0.0f, 1.0f, 0.0f});
}

TEST(ViewportGridPlacementPolicyTests,
     SnappedAndLockedTopBottomCoverScreenCornersRegardlessOfCameraUp) {
  for (const QVec2 viewport : {QVec2{1600.0f, 600.0f},
                              QVec2{500.0f, 1000.0f}}) {
    for (const int sign : {-1, 1}) {
      for (const QVec3 authored_up : {QVec3{1.0f, 0.0f, 0.0f},
                                      QVec3{0.0f, 0.0f, 1.0f},
                                      QVec3{0.0f, 0.0f, -1.0f}}) {
        for (const bool snapped : {false, true}) {
          SCOPED_TRACE(::testing::Message()
                       << "viewport " << viewport.x << 'x' << viewport.y
                       << " sign " << sign << " up " << authored_up.x << ','
                       << authored_up.z << " snapped " << snapped);
          ViewportCameraController camera;
          camera.set_viewport_size(viewport.x, viewport.y);
          const QVec3 target{12.0f, 0.0f, -8.0f};
          ASSERT_TRUE(camera.restore_perspective_pose({
              .eye = target + QVec3{0.0f, 24.0f * sign, 0.0f},
              .target = target,
              .up = authored_up,
          }));
          if (snapped) {
            camera.begin_drag({100.0f, 100.0f}, ViewportDragMode::OrbitSnap);
            camera.update_drag({101.0f, 100.0f});
            camera.end_drag();
            ASSERT_TRUE(camera.orbit_snap_orthographic_projection());
          } else {
            camera.view_axis(ViewportViewAxis::Y, sign);
          }
          ASSERT_EQ(camera.state().projection, ViewportProjection::Orthographic);
          const auto grid = ViewportGridPlacementPolicy::placement(
              camera, static_cast<std::uint32_t>(viewport.x),
              static_cast<std::uint32_t>(viewport.y));
          ASSERT_EQ(grid.plane, ViewportGridPlane::XZ);
          for (const QVec2 corner :
               {QVec2{0.0f, 0.0f}, QVec2{viewport.x, 0.0f},
                QVec2{0.0f, viewport.y}, viewport}) {
            const auto ray = camera.ray_from_viewport_point(corner);
            ASSERT_GT(std::fabs(ray.direction.y), 0.9f);
            const QVec3 hit = ray.origin + ray.direction *
                ((kViewportGridPlaneOffset - ray.origin.y) / ray.direction.y);
            // The 25% margin also keeps every corner before the edge fade.
            EXPECT_LE(std::fabs(hit.x - grid.origin.x),
                      grid.plane_size.x * 0.401f);
            EXPECT_LE(std::fabs(hit.z - grid.origin.z),
                      grid.plane_size.y * 0.401f);
          }
        }
      }
    }
  }
}

TEST(ViewportGridPlacementPolicyTests,
     TranslatedAxisViewsKeepTheirWorldAlignedGridInsideCameraClips) {
  for (const ViewportViewAxis axis :
       {ViewportViewAxis::X, ViewportViewAxis::Y, ViewportViewAxis::Z}) {
    const QVec3 axis_vector = axis == ViewportViewAxis::X
                                 ? QVec3{1.0f, 0.0f, 0.0f}
                             : axis == ViewportViewAxis::Y
                                 ? QVec3{0.0f, 1.0f, 0.0f}
                                 : QVec3{0.0f, 0.0f, 1.0f};
    for (const int sign : {-1, 1}) {
      for (const float translation : {-100.0f, 100.0f}) {
        for (const bool snapped : {false, true}) {
          SCOPED_TRACE(::testing::Message()
                       << "axis " << static_cast<int>(axis) << " sign " << sign
                       << " translation " << translation << " snap " << snapped);
          ViewportCameraController camera;
          camera.set_viewport_size(1200.0f, 600.0f);
          const QVec3 target = axis_vector * translation;
          ASSERT_TRUE(camera.restore_perspective_pose({
              .eye = target + axis_vector * (24.0f * sign),
              .target = target,
              .up = axis == ViewportViewAxis::Y ? QVec3{0.0f, 0.0f, 1.0f}
                                               : QVec3{0.0f, 1.0f, 0.0f},
          }));
          if (snapped) {
            camera.begin_drag({100.0f, 100.0f}, ViewportDragMode::Orbit);
            camera.update_drag({100.0f, 100.0f}, ViewportDragMode::OrbitSnap);
            camera.end_drag();
            ASSERT_TRUE(camera.orbit_snap_orthographic_projection());
          } else {
            camera.view_axis(axis, sign);
          }
          ASSERT_EQ(camera.state().projection, ViewportProjection::Orthographic);
          const ViewportCameraPose pose = camera.pose();
          const QVec3 forward = normalize(pose.target - pose.eye);
          for (const QVec2 clips : {QVec2{0.05f, 64.0f}, QVec2{32.0f, 64.0f},
                                   QVec2{0.05f, 192.0f},
                                   QVec2{32.0f, 32.001f},
                                   QVec2{999999.0f, 1000000.0f}}) {
            camera.set_clip_planes(clips.x, clips.y);
            const auto grid =
                ViewportGridPlacementPolicy::placement(camera, 1200u, 600u);
            const float grid_depth = dot(grid.origin - pose.eye, forward);
            EXPECT_GT(grid_depth, camera.state().near_plane);
            EXPECT_LT(grid_depth, camera.state().far_plane);
            // Relocating only the plane's normal preserves world grid positions.
            EXPECT_NEAR(dot(grid.origin - pose.target, grid.axes.u_axis),
                        0.0f, 0.001f);
            EXPECT_NEAR(dot(grid.origin - pose.target, grid.axes.v_axis),
                        0.0f, 0.001f);
            expect_vec3_near(camera.pose().eye, pose.eye);
            expect_vec3_near(camera.pose().target, pose.target);
            expect_vec3_near(camera.pose().up, pose.up);
            EXPECT_FLOAT_EQ(camera.state().near_plane, clips.x);
            EXPECT_FLOAT_EQ(camera.state().far_plane, clips.y);
          }
        }
      }
    }
  }
}

