RenderToolPreviewMeshRecord preview_match_test_record(bool dynamic_positions) {
  MeshGeometryPayload geometry;
  geometry.vertices = {
      MeshVertex{.position = {0.0f, 0.0f, 0.0f},
                 .normal = {0.0f, 0.0f, 1.0f},
                 .uv = {0.0f, 0.0f},
                 .rgba = 0xffffffffu,
                 .source_vertex_id = 1u},
      MeshVertex{.position = {1.0f, 0.0f, 0.0f},
                 .normal = {0.0f, 0.0f, 1.0f},
                 .uv = {1.0f, 0.0f},
                 .rgba = 0xffffffffu,
                 .source_vertex_id = 2u},
      MeshVertex{.position = {0.0f, 1.0f, 0.0f},
                 .normal = {0.0f, 0.0f, 1.0f},
                 .uv = {0.0f, 1.0f},
                 .rgba = 0xffffffffu,
                 .source_vertex_id = 3u},
  };
  geometry.indices = {0u, 1u, 2u};
  geometry.primitives = {
      {.index_offset = 0u, .index_count = 3u, .material_slot = 0u}};

  RenderToolPreviewMeshRecord record;
  record.source_object_id = 41;
  record.source_entity = 73u;
  record.visibility_entity = 79u;
  record.mesh.replace_geometry(std::move(geometry));
  record.dynamic_positions = dynamic_positions;
  record.layout_key = dynamic_positions ? 101u : 0u;
  record.position_revision = dynamic_positions ? 1u : 0u;
  return record;
}

TEST(ToolPreviewRenderableCacheTests,
     ExactClaimBucketsVisitEquivalentGroupsOnceInStableOrder) {
  const auto run = [](std::size_t group_count) {
    const RenderToolPreviewMeshRecord prototype =
        preview_match_test_record(false);
    const std::vector<RenderToolPreviewMeshRecord> retained(group_count,
                                                            prototype);
    const std::vector<RenderToolPreviewMeshRecord> submitted(group_count,
                                                             prototype);
    return ToolPreviewRenderableCacheTestPeer::match(retained, submitted);
  };

  const auto small = run(32u);
  const auto large = run(256u);
  ASSERT_EQ(small.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::Exact);
  ASSERT_EQ(large.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::Exact);
  ASSERT_EQ(large.candidate_indices.size(), 256u);
  for (std::size_t index = 0u; index < large.candidate_indices.size();
       ++index) {
    EXPECT_EQ(large.candidate_indices[index], index);
  }
  EXPECT_EQ(small.counters.exact_match_candidate_visits, 32u);
  EXPECT_EQ(large.counters.exact_match_candidate_visits, 256u);
  EXPECT_EQ(large.counters.exact_match_candidate_visits,
            small.counters.exact_match_candidate_visits * 8u);
  EXPECT_EQ(large.counters.structural_match_candidate_visits, 0u);
}

TEST(ToolPreviewRenderableCacheTests,
     ExactLayoutWildcardMatchingKeepsEarliestCompatibleAssociation) {
  const RenderToolPreviewMeshRecord prototype =
      preview_match_test_record(true);
  std::vector<RenderToolPreviewMeshRecord> retained(4u, prototype);
  retained[0].layout_key = 0u;
  retained[1].layout_key = 7u;
  retained[2].layout_key = 7u;
  retained[3].layout_key = 0u;

  std::vector<RenderToolPreviewMeshRecord> submitted(4u, prototype);
  submitted[0].layout_key = 7u;
  submitted[1].layout_key = 7u;
  submitted[2].layout_key = 9u;
  submitted[3].layout_key = 0u;

  const auto outcome =
      ToolPreviewRenderableCacheTestPeer::match(retained, submitted);
  ASSERT_EQ(outcome.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::Exact);
  EXPECT_EQ(outcome.candidate_indices,
            (std::vector<std::size_t>{0u, 1u, 3u, 2u}));
  EXPECT_LE(outcome.counters.exact_match_candidate_visits,
            retained.size() * 3u);
  EXPECT_EQ(outcome.counters.structural_match_candidate_visits, 0u);
}

TEST(ToolPreviewRenderableCacheTests,
     DynamicLayoutReusesGroupWhenDerivedAttributesAndIndicesChange) {
  RenderToolPreviewMeshRecord retained = preview_match_test_record(true);
  RenderToolPreviewMeshRecord submitted = retained;
  MeshGeometryPayload &geometry = submitted.mesh.edit_geometry();
  geometry.vertices[0].position = {0.25f, 0.0f, 0.5f};
  geometry.vertices[0].normal = {0.0f, 1.0f, 0.0f};
  geometry.vertices[0].uv = {0.25f, 0.5f};
  geometry.indices = {0u, 2u, 1u};
  submitted.position_revision = retained.position_revision + 1u;

  const auto outcome = ToolPreviewRenderableCacheTestPeer::match(
      std::vector<RenderToolPreviewMeshRecord>{retained},
      std::vector<RenderToolPreviewMeshRecord>{submitted});

  ASSERT_EQ(outcome.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::Exact);
  EXPECT_EQ(outcome.candidate_indices,
            (std::vector<std::size_t>{0u}));
  EXPECT_EQ(outcome.counters.structural_match_candidate_visits, 0u);
}

TEST(ToolPreviewRenderableCacheTests,
     CullingChangeCannotReuseAStalePreviewMaterial) {
  RenderToolPreviewMeshRecord retained = preview_match_test_record(true);
  retained.double_sided = false;
  RenderToolPreviewMeshRecord submitted = retained;
  submitted.double_sided = true;

  const auto outcome = ToolPreviewRenderableCacheTestPeer::match(
      std::vector<RenderToolPreviewMeshRecord>{retained},
      std::vector<RenderToolPreviewMeshRecord>{submitted});

  EXPECT_EQ(outcome.kind, ToolPreviewRenderableCacheTestPeer::MatchKind::None);
  EXPECT_TRUE(outcome.candidate_indices.empty());
}

TEST(ToolPreviewRenderableCacheTests,
     ExplicitInstancePlanRetainsHighWaterChunksAcrossCountSweeps) {
  const ToolPreviewInstancePlan maximum =
      plan_tool_preview_instances(128u, 64u);
  ASSERT_EQ(maximum.chunks.size(), 2u);
  EXPECT_EQ(maximum.new_chunk_count, 2u);
  EXPECT_EQ(maximum.allocated_capacity, 128u);
  EXPECT_EQ(maximum.chunks[0].transform_offset, 0u);
  EXPECT_EQ(maximum.chunks[0].active_count, 64u);
  EXPECT_EQ(maximum.chunks[1].transform_offset, 64u);
  EXPECT_EQ(maximum.chunks[1].active_count, 64u);

  const std::array<std::size_t, 2u> retained{{64u, 64u}};
  const ToolPreviewInstancePlan shrunk =
      plan_tool_preview_instances(4u, 64u, retained);
  ASSERT_EQ(shrunk.chunks.size(), 2u);
  EXPECT_EQ(shrunk.new_chunk_count, 0u);
  EXPECT_EQ(shrunk.allocated_capacity, 128u);
  EXPECT_EQ(shrunk.chunks[0].transform_offset, 0u);
  EXPECT_EQ(shrunk.chunks[0].active_count, 4u);
  EXPECT_EQ(shrunk.chunks[1].transform_offset, 4u);
  EXPECT_EQ(shrunk.chunks[1].active_count, 0u);

  const ToolPreviewInstancePlan regrown =
      plan_tool_preview_instances(128u, 64u, retained);
  ASSERT_EQ(regrown.chunks.size(), 2u);
  EXPECT_EQ(regrown.new_chunk_count, 0u);
  EXPECT_EQ(regrown.chunks[0].active_count, 64u);
  EXPECT_EQ(regrown.chunks[1].active_count, 64u);

  std::vector<std::size_t> capacities;
  std::size_t total_chunk_creations = 0u;
  for (std::size_t count = 2u; count <= 128u; ++count) {
    const ToolPreviewInstancePlan plan =
        plan_tool_preview_instances(count, 64u, capacities);
    total_chunk_creations += plan.new_chunk_count;
    capacities.clear();
    for (const ToolPreviewInstanceChunkPlan &chunk : plan.chunks) {
      capacities.push_back(chunk.capacity);
    }
  }
  EXPECT_EQ(total_chunk_creations, 2u)
      << "count sweeps allocate by device chunks, not by station count";
}

TEST(ToolPreviewLightCacheTests,
     LightPoolPlanGrowsOnlyTheHighWaterDelta) {
  std::vector<std::size_t> retained;
  std::size_t total_created = 0u;
  for (std::size_t count = 2u; count <= 128u; ++count) {
    const std::array<std::size_t, 1u> requested{{count}};
    const ToolPreviewLightPoolPlan plan =
        plan_tool_preview_light_pools(requested, retained);
    total_created += plan.new_proxy_count;
    retained = plan.retained_capacities;
  }
  EXPECT_EQ(total_created, 128u);
  ASSERT_EQ(retained, (std::vector<std::size_t>{128u}));

  const std::array<std::size_t, 1u> shrunk{{4u}};
  const ToolPreviewLightPoolPlan shrink_plan =
      plan_tool_preview_light_pools(shrunk, retained);
  EXPECT_EQ(shrink_plan.new_proxy_count, 0u);
  EXPECT_EQ(shrink_plan.retained_capacities, retained);

  const std::array<std::size_t, 1u> regrown{{128u}};
  const ToolPreviewLightPoolPlan regrow_plan =
      plan_tool_preview_light_pools(regrown,
                                    shrink_plan.retained_capacities);
  EXPECT_EQ(regrow_plan.new_proxy_count, 0u);
  EXPECT_EQ(regrow_plan.retained_capacities, retained);
}

TEST(ToolPreviewRenderableCacheTests,
     ExplicitInstanceCountChangesReuseRetainedChunkCapacity) {
  RenderToolPreviewMeshRecord retained = preview_match_test_record(false);
  retained.instance_transforms.assign(4u, QMat4{});

  RenderToolPreviewMeshRecord within_capacity = retained;
  within_capacity.instance_transforms.assign(kMeshTextureMappingCapacity,
                                             QMat4{});
  const auto reused = ToolPreviewRenderableCacheTestPeer::match(
      std::vector<RenderToolPreviewMeshRecord>{retained},
      std::vector<RenderToolPreviewMeshRecord>{within_capacity});
  ASSERT_EQ(reused.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::Exact);
  EXPECT_EQ(reused.candidate_indices,
            (std::vector<std::size_t>{0u}));

  RenderToolPreviewMeshRecord beyond_capacity = retained;
  beyond_capacity.instance_transforms.assign(kMeshTextureMappingCapacity + 1u,
                                             QMat4{});
  const auto rejected = ToolPreviewRenderableCacheTestPeer::match(
      std::vector<RenderToolPreviewMeshRecord>{retained},
      std::vector<RenderToolPreviewMeshRecord>{beyond_capacity});
  EXPECT_EQ(rejected.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::None);
  EXPECT_TRUE(rejected.candidate_indices.empty());
}

TEST(ToolPreviewRenderableCacheTests,
     StructuralClaimBucketsScaleLinearlyAndPreserveReuseOrder) {
  const auto run = [](std::size_t group_count) {
    const RenderToolPreviewMeshRecord prototype =
        preview_match_test_record(true);
    std::vector<RenderToolPreviewMeshRecord> retained(group_count, prototype);
    std::vector<RenderToolPreviewMeshRecord> submitted(group_count, prototype);
    for (std::size_t index = 0u; index < group_count; ++index) {
      retained[index].source_object_id = static_cast<int>(index);
      retained[index].source_entity = static_cast<EntityId>(100u + index);
      retained[index].visibility_entity =
          static_cast<EntityId>(200u + index);
      submitted[index].source_object_id =
          static_cast<int>(1000u + index);
      submitted[index].source_entity =
          static_cast<EntityId>(2000u + index);
      submitted[index].visibility_entity =
          static_cast<EntityId>(3000u + index);
    }
    return ToolPreviewRenderableCacheTestPeer::match(retained, submitted);
  };

  const auto small = run(32u);
  const auto large = run(256u);
  ASSERT_EQ(small.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::Structural);
  ASSERT_EQ(large.kind,
            ToolPreviewRenderableCacheTestPeer::MatchKind::Structural);
  ASSERT_EQ(large.candidate_indices.size(), 256u);
  for (std::size_t index = 0u; index < large.candidate_indices.size();
       ++index) {
    EXPECT_EQ(large.candidate_indices[index], index);
  }
  EXPECT_EQ(large.counters.exact_match_candidate_visits, 0u);
  EXPECT_EQ(small.counters.structural_match_candidate_visits, 32u);
  EXPECT_EQ(large.counters.structural_match_candidate_visits, 256u);
  EXPECT_EQ(large.counters.structural_match_candidate_visits,
            small.counters.structural_match_candidate_visits * 8u);
}

