TEST(SceneSessionTests,
     ReplaceDocumentAdvancesSceneRevisionPastPreviousDocument) {
  SceneSession session;
  for (int i = 0; i < 8; ++i) {
    const EntityId entity =
        session.scene().create_entity("Previous Entity " + std::to_string(i));
    ASSERT_NE(entity, kInvalidEntityId);
  }
  const std::uint64_t previous_scene_revision = session.scene().revision();
  for (int i = 0; i < 8; ++i) {
    ASSERT_NE(session.assets().add_mesh(MeshAsset{}), kInvalidAssetId);
  }
  const std::uint64_t previous_asset_revision = session.assets().revision();
  session.mark_clean();
  EXPECT_FALSE(session.dirty());

  SceneContentDocument replacement;
  const EntityId light =
      replacement.scene().create_entity("Loaded Light", EntityKind::Light);
  ASSERT_NE(light, kInvalidEntityId);
  replacement.scene().set_light(light,
                                LightComponent{.type = LightType::Point});
  MeshAsset loaded_mesh;
  loaded_mesh.name = "Loaded Mesh";
  const AssetId replacement_mesh =
      replacement.assets().add_mesh(1u, std::move(loaded_mesh));
  ASSERT_EQ(replacement_mesh, 1u);
  ASSERT_LT(replacement.scene().revision(), previous_scene_revision);
  ASSERT_LT(replacement.assets().revision(), previous_asset_revision);

  session.replace_document(std::move(replacement));

  EXPECT_GT(session.scene().revision(), previous_scene_revision);
  EXPECT_GT(session.assets().revision(), previous_asset_revision);
  EXPECT_GT(session.assets().mesh_revision(replacement_mesh).value,
            previous_asset_revision);
  EXPECT_FALSE(session.dirty());
  ASSERT_NE(session.scene().light(light), nullptr);
  EXPECT_EQ(session.scene().light(light)->type, LightType::Point);
}

TEST(SceneSessionTests,
     ReplaceDocumentClearsPersistentQuickAndArrayToolState) {
  {
    SceneSession session;
    QuaderEditorApi editor(
        QuaderApiSessionInternalAccess::from_scene_session(session));
    const QuaderApiResult<QuaderModelingObjectRef> source =
        editor.modeling().create_box(
            QuaderBounds{.min = {-1.0f, -1.0f, -1.0f},
                         .max = {1.0f, 1.0f, 1.0f}},
            "Old Pivot Source");
    ASSERT_TRUE(source.ok()) << source.error_message();
    ASSERT_TRUE(editor.selection().select_object(source.value()).ok());
    ASSERT_TRUE(editor.tools().activate(ViewportToolId::Pivot).ok());
    session.pivot().set_persistent_preview_position({3.0f, 4.0f, 5.0f});
    session.pivot().begin_quick({6.0f, 7.0f, 8.0f});
    ASSERT_TRUE(session.pivot().persistent_active());
    ASSERT_TRUE(session.pivot().selection_pivot_override().valid);

    SceneContentDocument replacement;
    const EntityId replacement_light = replacement.scene().create_entity_with_id(
        source.value().entity, "Replacement Light", EntityKind::Light);
    ASSERT_EQ(replacement_light, source.value().entity);
    replacement.scene().set_light(replacement_light,
                                  LightComponent{.type = LightType::Point});
    TransformComponent replacement_transform =
        *replacement.scene().transform(replacement_light);
    replacement_transform.position = {9.0f, 8.0f, 7.0f};
    replacement.scene().set_transform(replacement_light,
                                      replacement_transform);

    session.replace_document(std::move(replacement));

    EXPECT_FALSE(session.pivot().persistent_active());
    EXPECT_FALSE(session.pivot().selection_pivot_override().valid);
    EXPECT_FALSE(session.native_tools().has_pending_tool());
    EXPECT_FALSE(editor.tools().active_settings().active);
    const QuaderApiVoidResult applied =
        editor.tools().commit_active_tool_preview();
    EXPECT_FALSE(applied.ok());
    ASSERT_NE(session.scene().transform(replacement_light), nullptr);
    expect_vec3_near(session.scene().transform(replacement_light)->position,
                     {9.0f, 8.0f, 7.0f});
  }

  {
    SceneSession session;
    QuaderEditorApi editor(
        QuaderApiSessionInternalAccess::from_scene_session(session));
    const QuaderApiResult<QuaderModelingObjectRef> source =
        editor.modeling().create_box(
            QuaderBounds{.min = {-1.0f, -1.0f, -1.0f},
                         .max = {1.0f, 1.0f, 1.0f}},
            "Old Array Source");
    ASSERT_TRUE(source.ok()) << source.error_message();
    ASSERT_TRUE(editor.selection().select_object(source.value()).ok());
    ASSERT_TRUE(editor.tools().activate(ViewportToolId::LinearArray).ok());
    ASSERT_TRUE(session.linear_array().has_session());

    SceneContentDocument replacement;
    const EntityId replacement_light = replacement.scene().create_entity_with_id(
        source.value().entity, "Replacement Array Light", EntityKind::Light);
    ASSERT_EQ(replacement_light, source.value().entity);
    replacement.scene().set_light(replacement_light,
                                  LightComponent{.type = LightType::Point});

    session.replace_document(std::move(replacement));

    EXPECT_FALSE(session.linear_array().has_session());
    EXPECT_FALSE(session.native_tools().has_pending_tool());
    EXPECT_TRUE(editor.render().tool_preview_meshes().empty());
    EXPECT_FALSE(editor.tools().commit_active_tool_preview().ok());
  }

  {
    SceneSession session;
    QuaderEditorApi editor(
        QuaderApiSessionInternalAccess::from_scene_session(session));
    const QuaderApiResult<QuaderModelingObjectRef> source =
        editor.modeling().create_box(
            QuaderBounds{.min = {-1.0f, -1.0f, -1.0f},
                         .max = {1.0f, 1.0f, 1.0f}},
            "Old Radial Array Source");
    ASSERT_TRUE(source.ok()) << source.error_message();
    ASSERT_TRUE(editor.selection().select_object(source.value()).ok());
    ASSERT_TRUE(editor.tools().activate(ViewportToolId::RadialArray).ok());
    ASSERT_TRUE(session.radial_array()
                    .update_center_candidate({}, {0.0f, 1.0f, 0.0f}, 1.0)
                    .ok);
    ASSERT_TRUE(session.radial_array().lock_center().ok);
    ASSERT_TRUE(session.radial_array().preview_state().active);

    SceneContentDocument replacement;
    const EntityId replacement_light = replacement.scene().create_entity_with_id(
        source.value().entity, "Replacement Radial Light", EntityKind::Light);
    ASSERT_EQ(replacement_light, source.value().entity);
    replacement.scene().set_light(replacement_light,
                                  LightComponent{.type = LightType::Point});

    session.replace_document(std::move(replacement));

    EXPECT_FALSE(session.radial_array().has_session());
    EXPECT_FALSE(session.native_tools().has_pending_tool());
    EXPECT_TRUE(editor.render().tool_preview_meshes().empty());
    EXPECT_FALSE(editor.tools().commit_active_tool_preview().ok());
  }
}

TEST(SceneSessionTests,
     ReplaceDocumentClearsSceneTransformPreviewBeforeInstallingReplacement) {
  SceneSession session;
  QuaderEditorApi editor(
      QuaderApiSessionInternalAccess::from_scene_session(session));
  const QuaderApiResult<QuaderModelingObjectRef> source =
      editor.modeling().create_box(
          QuaderBounds{.min = {-1.0f, -1.0f, -1.0f},
                       .max = {1.0f, 1.0f, 1.0f}},
          "Old Transform Preview Source");
  ASSERT_TRUE(source.ok()) << source.error_message();

  QuaderApiResult<QuaderTransformDragPreview> begin =
      editor.modeling().begin_transform_drag(
          test_api_x_move_drag_begin_request());
  ASSERT_TRUE(begin.ok()) << begin.error_message();
  ASSERT_TRUE(begin.value().active);
  ASSERT_TRUE(begin.value().scene_transform);
  QuaderApiResult<QuaderTransformDragPreview> update =
      editor.modeling().update_transform_drag(
          test_api_x_move_drag_update_request(2.0f));
  ASSERT_TRUE(update.ok()) << update.error_message();
  ASSERT_NE(session.scene().transform(source.value().entity), nullptr);
  EXPECT_NEAR(session.scene().transform(source.value().entity)->position.x,
              2.0f, 0.001f);

  SceneContentDocument replacement;
  const EntityId replacement_entity = replacement.scene().create_entity_with_id(
      source.value().entity, "Replacement Entity", EntityKind::Empty);
  ASSERT_EQ(replacement_entity, source.value().entity);
  TransformComponent replacement_transform =
      *replacement.scene().transform(replacement_entity);
  replacement_transform.position = {99.0f, 8.0f, 7.0f};
  replacement.scene().set_transform(replacement_entity,
                                    replacement_transform);

  session.replace_document(std::move(replacement));

  EXPECT_FALSE(session.modeling().transform_drag_active());
  ASSERT_NE(session.scene().transform(replacement_entity), nullptr);
  expect_vec3_near(session.scene().transform(replacement_entity)->position,
                   {99.0f, 8.0f, 7.0f});

  const QuaderApiVoidResult late_cancel =
      editor.modeling().cancel_transform_drag();
  ASSERT_TRUE(late_cancel.ok()) << late_cancel.error_message();
  EXPECT_FALSE(late_cancel.changed());
  ASSERT_NE(session.scene().transform(replacement_entity), nullptr);
  expect_vec3_near(session.scene().transform(replacement_entity)->position,
                   {99.0f, 8.0f, 7.0f});
}

TEST(SceneSessionTests, PublicHistoryIgnoresUntrackedModelingSessionHistory) {
  SceneSession session;
  QuaderEditorApi editor(
      QuaderApiSessionInternalAccess::from_scene_session(session));
  const auto entity_named = [&](std::string_view name) {
    const std::vector<QuaderEntitySnapshot> entities =
        editor.query().entities();
    return std::find_if(entities.begin(), entities.end(),
                        [&](const QuaderEntitySnapshot &snapshot) {
                          return snapshot.name == name;
                        }) != entities.end();
  };

  const auto hidden = session.modeling().create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f}, .max = {1.0f, 1.0f, 1.0f}},
      .name = "Hidden Modeling Box",
  });
  ASSERT_TRUE(hidden.ok) << hidden.message;
  ASSERT_TRUE(entity_named("Hidden Modeling Box"));

  EXPECT_FALSE(editor.history().can_undo());
  EXPECT_FALSE(editor.history().can_redo());

  const QuaderApiVoidResult direct_undo = editor.history().undo();
  EXPECT_FALSE(direct_undo.ok());
  EXPECT_FALSE(direct_undo.changed());
  EXPECT_EQ(direct_undo.error_message(), "No command to undo");
  EXPECT_TRUE(entity_named("Hidden Modeling Box"));

  const QuaderApiVoidResult command_undo =
      editor.commands().execute(quader_command::kEditUndo);
  EXPECT_FALSE(command_undo.ok());
  EXPECT_FALSE(command_undo.changed());
  EXPECT_EQ(command_undo.error_message(), "Command is disabled.");
  EXPECT_EQ(command_undo.revisions.scene_revision,
            editor.revisions().scene_revision);
  EXPECT_EQ(command_undo.revisions.modeling_content_revision,
            editor.revisions().modeling_content_revision);
  EXPECT_TRUE(entity_named("Hidden Modeling Box"));

  const QuaderApiVoidResult unknown_tool =
      editor.tools().activate("__missing_tool__");
  EXPECT_FALSE(unknown_tool.ok());
  EXPECT_EQ(unknown_tool.error_message(), "Unknown viewport tool.");
  EXPECT_EQ(unknown_tool.revisions.scene_revision,
            editor.revisions().scene_revision);
  EXPECT_EQ(unknown_tool.revisions.modeling_content_revision,
            editor.revisions().modeling_content_revision);
}

TEST(SceneSessionTests,
     QuickPivotOverrideFeedsTransformPivotAndClearsOnSelectionChange) {
  SceneSession session;
  QuaderEditorApi editor(
      QuaderApiSessionInternalAccess::from_scene_session(session));
  const QuaderApiResult<QuaderModelingObjectRef> first =
      editor.modeling().create_box(
          QuaderBounds{.min = {-1.0f, -1.0f, -1.0f}, .max = {1.0f, 1.0f, 1.0f}},
          "Quick Pivot A");
  ASSERT_TRUE(first.ok()) << first.error_message();
  const QuaderApiResult<QuaderModelingObjectRef> second =
      editor.modeling().create_box(
          QuaderBounds{.min = {-1.0f, -1.0f, -1.0f}, .max = {1.0f, 1.0f, 1.0f}},
          "Quick Pivot B");
  ASSERT_TRUE(second.ok()) << second.error_message();
  ASSERT_TRUE(editor.selection()
                  .select_objects({first.value().entity, second.value().entity},
                                  second.value().entity)
                  .ok());

  session.pivot().begin_quick({4.0f, 5.0f, 6.0f});
  EXPECT_TRUE(session.pivot().quick_edit_active());
  std::optional<QVec3> pivot = editor.query().selection_transform_pivot();
  ASSERT_TRUE(pivot.has_value());
  expect_vec3_near(*pivot, {4.0f, 5.0f, 6.0f});

  session.pivot().set_quick_preview_position({7.0f, 8.0f, 9.0f});
  session.pivot().end_quick_edit();
  EXPECT_FALSE(session.pivot().quick_edit_active());
  pivot = editor.query().selection_transform_pivot();
  ASSERT_TRUE(pivot.has_value());
  expect_vec3_near(*pivot, {7.0f, 8.0f, 9.0f});

  ASSERT_TRUE(editor.selection().select_object(first.value()).ok());
  pivot = editor.query().selection_transform_pivot();
  ASSERT_TRUE(pivot.has_value());
  EXPECT_TRUE(length(*pivot - QVec3{7.0f, 8.0f, 9.0f}) > 0.0001f);

  session.pivot().begin_quick({1.0f, 2.0f, 3.0f});
  session.pivot().end_quick_edit();
  pivot = editor.query().selection_transform_pivot();
  ASSERT_TRUE(pivot.has_value());
  expect_vec3_near(*pivot, {1.0f, 2.0f, 3.0f});

  ASSERT_TRUE(editor.selection().clear().ok());
  EXPECT_FALSE(editor.query().selection_transform_pivot().has_value());
}

TEST(SceneSessionTests,
     ServiceCreatesSessionsWithDocumentAssetsAndCommandsWiredTogether) {
  SceneSessionService service;
  std::unique_ptr<SceneSession> session =
      service.create_session(SceneContentDocumentRecord{
          .id = 42,
          .name = "Architecture Session",
      });
  ASSERT_NE(session, nullptr);
  EXPECT_EQ(session->document().id(), 42u);
  EXPECT_EQ(session->document().name(), "Architecture Session");
  EXPECT_EQ(&session->scene(), &session->document().scene());
  EXPECT_EQ(&session->assets(), &session->document().assets());

  const AssetId material = session->assets().add_material(
      make_default_quader_material("Session Material"));
  ASSERT_NE(session->document().assets().material(material), nullptr);
  EXPECT_EQ(session->document().assets().material(material)->name,
            "Session Material");

  const DocumentCreateEntityResult result =
      session->document_commands().create_entity(
          "Session Entity", EntityKind::Mesh, kInvalidEntityId, {});
  ASSERT_TRUE(result.ok) << result.message;
  const EntityId entity = result.entity;
  ASSERT_NE(entity, kInvalidEntityId);
  EXPECT_TRUE(session->scene().exists(entity));
  EXPECT_TRUE(session->history().can_undo());
  ASSERT_TRUE(session->history().undo().ok);
  EXPECT_FALSE(session->scene().exists(entity));

  SceneContentDocument existing(SceneContentDocumentRecord{
      .id = 99,
      .name = "Opened Session",
  });
  const EntityId authored_entity =
      existing.scene().create_entity("Authored Mesh");
  const EditorObjectId object =
      existing.scene().editor_object_id(authored_entity);
  std::unique_ptr<SceneSession> opened =
      service.open_session(std::move(existing));
  ASSERT_NE(opened, nullptr);
  EXPECT_EQ(opened->document().id(), 99u);
  EXPECT_EQ(opened->document().name(), "Opened Session");
  EXPECT_EQ(opened->scene().entity_for_editor_object_id(object),
            authored_entity);
}

TEST(SceneSessionTests, ReadViewExposesConstProjectSceneAndAssetState) {
  static_assert(
      std::is_same_v<decltype(std::declval<SceneSessionReadView>().document),
                     const SceneContentDocument &>);
  static_assert(
      std::is_same_v<decltype(std::declval<SceneSessionReadView>().scene),
                     const SceneDocument &>);
  static_assert(
      std::is_same_v<decltype(std::declval<SceneSessionReadView>().assets),
                     const AssetRegistry &>);

  SceneSession session;
  const SceneContentRevisionStamp before = session.content_revision_stamp();
  const SceneSessionReadView view = session.read_view();

  EXPECT_EQ(&view.document, &std::as_const(session).document());
  EXPECT_EQ(&view.scene, &std::as_const(session).scene());
  EXPECT_EQ(&view.assets, &std::as_const(session).assets());
  EXPECT_EQ(&view.modeling, &std::as_const(session).modeling());
  EXPECT_EQ(&view.selection, &std::as_const(session).selection());
  EXPECT_EQ(view.document.revision(), before.project_revision);
  EXPECT_EQ(view.scene.revision(), before.scene_revision);
  EXPECT_EQ(view.assets.revision(), before.asset_revision);
  EXPECT_EQ(session.content_revision_stamp(), before);
}

TEST(SceneSessionTests,
     DefaultAssetBootstrapServiceCreatesRuntimeDefaultMaterial) {
  SceneSession session;
  const ProjectDefaultAssets defaults =
      ProjectAssetBootstrapService{}.bootstrap_default_assets(session);

  ASSERT_NE(defaults.albedo_texture, kInvalidAssetId);
  ASSERT_NE(defaults.roughness_texture, kInvalidAssetId);
  ASSERT_NE(defaults.default_material, kInvalidAssetId);
  const SceneSessionReadView view = session.read_view();
  EXPECT_EQ(view.assets.texture_count(), 2u);
  EXPECT_EQ(view.assets.material_count(), 1u);

  const TextureAsset *albedo = view.assets.texture(defaults.albedo_texture);
  ASSERT_NE(albedo, nullptr);
  EXPECT_EQ(std::string_view(albedo->name), kDefaultMaterialAlbedoTextureName);
  EXPECT_EQ(albedo->usage, TextureUsage::BaseColor);
  EXPECT_EQ(albedo->color_space, TextureColorSpace::Srgb);
  EXPECT_EQ(albedo->source_path.generic_string(),
            std::string(kDefaultMaterialAlbedoTexturePackagePath));

  const TextureAsset *roughness =
      view.assets.texture(defaults.roughness_texture);
  ASSERT_NE(roughness, nullptr);
  EXPECT_EQ(std::string_view(roughness->name),
            kDefaultMaterialRoughnessTextureName);
  EXPECT_EQ(roughness->usage, TextureUsage::Roughness);
  EXPECT_EQ(roughness->color_space, TextureColorSpace::Linear);
  EXPECT_EQ(roughness->source_path.generic_string(),
            std::string(kDefaultMaterialRoughnessTexturePackagePath));

  const MaterialDocument *material =
      view.assets.material(defaults.default_material);
  ASSERT_NE(material, nullptr);
  EXPECT_EQ(material->name, "Default Quader");
  EXPECT_EQ(
      material_texture_slot_asset(*material, material_texture_slot::kBaseColor),
      std::optional<AssetId>{defaults.albedo_texture});
  EXPECT_FALSE(
      material_texture_slot_asset(*material, material_texture_slot::kRoughness)
          .has_value());

  const std::uint64_t revision = session.assets().revision();
  const ProjectDefaultAssets repeated =
      ProjectAssetBootstrapService{}.bootstrap_default_assets(session);
  EXPECT_EQ(repeated.albedo_texture, defaults.albedo_texture);
  EXPECT_EQ(repeated.roughness_texture, defaults.roughness_texture);
  EXPECT_EQ(repeated.default_material, defaults.default_material);
  EXPECT_EQ(session.assets().revision(), revision);
}

TEST(SceneSessionTests,
     DocumentReplacementFinalizerRebindsCurrentDefaultAssetsBeforeCleanStamp) {
  SceneSession session;
  ProjectDefaultAssets current =
      ProjectAssetBootstrapService{}.bootstrap_default_assets(session);
  ASSERT_NE(current.default_material, kInvalidAssetId);
  const AssetId previous_default = current.default_material;
  session.mark_clean();
  session.set_document_replacement_finalizer(
      [&current](SceneSession &replaced) {
        current = ProjectAssetBootstrapService{}.bootstrap_default_assets(
            replaced);
      });

  SceneContentDocument replacement;
  MaterialDocument unrelated = make_default_quader_material("Unrelated");
  ASSERT_EQ(replacement.assets().add_material(previous_default,
                                              std::move(unrelated)),
            previous_default);
  session.replace_document(std::move(replacement));

  EXPECT_NE(current.default_material, previous_default);
  const MaterialDocument *material =
      session.assets().material(current.default_material);
  ASSERT_NE(material, nullptr);
  EXPECT_EQ(material->name, "Default Quader");
  EXPECT_FALSE(session.dirty());
}

TEST(SceneSessionTests,
     DefaultAssetBootstrapDoesNotAliasAuthoredAssetsByDisplayName) {
  SceneSession session;

  TextureAsset authored_albedo;
  authored_albedo.name = std::string(kDefaultMaterialAlbedoTextureName);
  authored_albedo.source_path =
      std::string(kDefaultMaterialAlbedoTexturePackagePath);
  authored_albedo.usage = TextureUsage::Normal;
  authored_albedo.color_space = TextureColorSpace::Linear;
  const AssetId authored_albedo_id =
      session.assets().add_texture(std::move(authored_albedo));

  MaterialDocument authored_material =
      make_default_quader_material("Default Quader");
  authored_material.metallic = 1.0f;
  const AssetId authored_material_id =
      session.assets().add_material(std::move(authored_material));

  const ProjectDefaultAssets defaults =
      ProjectAssetBootstrapService{}.bootstrap_default_assets(session);
  EXPECT_NE(defaults.albedo_texture, authored_albedo_id);
  EXPECT_NE(defaults.default_material, authored_material_id);
  ASSERT_NE(session.assets().texture(defaults.albedo_texture), nullptr);
  EXPECT_EQ(session.assets().texture(defaults.albedo_texture)->usage,
            TextureUsage::BaseColor);
  ASSERT_NE(session.assets().material(defaults.default_material), nullptr);
  EXPECT_FLOAT_EQ(session.assets().material(defaults.default_material)->metallic,
                  0.0f);

  const std::uint64_t revision = session.assets().revision();
  const ProjectDefaultAssets repeated =
      ProjectAssetBootstrapService{}.bootstrap_default_assets(session);
  EXPECT_EQ(repeated.albedo_texture, defaults.albedo_texture);
  EXPECT_EQ(repeated.default_material, defaults.default_material);
  EXPECT_EQ(session.assets().revision(), revision);
}


TEST(SceneSessionTests, DefaultAssetBootstrapPreservesAuthoredLambertMaterial) {
  SceneSession session;
  const ProjectDefaultAssets original =
      ProjectAssetBootstrapService{}.bootstrap_default_assets(session);
  ASSERT_TRUE(session.assets().update_material(
      original.default_material, [](MaterialDocument &material) {
        material.diffuse_model = MaterialDiffuseModel::Lambert;
      }));

  const ProjectDefaultAssets defaults =
      ProjectAssetBootstrapService{}.bootstrap_default_assets(session);
  EXPECT_NE(defaults.default_material, original.default_material);
  EXPECT_EQ(defaults.albedo_texture, original.albedo_texture);
  EXPECT_EQ(defaults.roughness_texture, original.roughness_texture);
  ASSERT_NE(session.assets().material(original.default_material), nullptr);
  EXPECT_EQ(session.assets().material(original.default_material)->diffuse_model,
            MaterialDiffuseModel::Lambert);
  ASSERT_NE(session.assets().material(defaults.default_material), nullptr);
  EXPECT_EQ(session.assets().material(defaults.default_material)->diffuse_model,
            MaterialDiffuseModel::Burley);

  const std::uint64_t revision = session.assets().revision();
  EXPECT_EQ(ProjectAssetBootstrapService{}.bootstrap_default_assets(session)
                .default_material,
            defaults.default_material);
  EXPECT_EQ(session.assets().revision(), revision);
}

TEST(DocumentCommandServiceTests, RecordsUndoRedoForNativeSceneEdits) {
  SceneDocument scene;
  const EntityId entity = scene.create_entity("Brush");
  EditorHistoryService history;
  DocumentCommandService commands(scene, history);

  DocumentCommandResult result = commands.rename_entity(entity, "Brush_1");
  ASSERT_TRUE(result.ok) << result.message;
  EXPECT_TRUE(result.changed);
  ASSERT_NE(scene.name(entity), nullptr);
  EXPECT_EQ(scene.name(entity)->name, "Brush_1");
  EXPECT_TRUE(history.can_undo());
  EXPECT_FALSE(history.can_redo());
  ASSERT_NE(history.undo_label(), nullptr);
  EXPECT_EQ(*history.undo_label(), "Rename Entity");

  result = history.undo();
  ASSERT_TRUE(result.ok) << result.message;
  ASSERT_NE(scene.name(entity), nullptr);
  EXPECT_EQ(scene.name(entity)->name, "Brush");
  EXPECT_FALSE(history.can_undo());
  EXPECT_TRUE(history.can_redo());

  result = history.redo();
  ASSERT_TRUE(result.ok) << result.message;
  ASSERT_NE(scene.name(entity), nullptr);
  EXPECT_EQ(scene.name(entity)->name, "Brush_1");

  TransformComponent transform;
  transform.position = {3.0f, 2.0f, 1.0f};
  ASSERT_TRUE(commands.set_transform(entity, transform).ok);
  ASSERT_NE(scene.transform(entity), nullptr);
  EXPECT_FLOAT_EQ(scene.transform(entity)->position.x, 3.0f);
  EXPECT_TRUE(history.undo().ok);
  ASSERT_NE(scene.transform(entity), nullptr);
  EXPECT_FLOAT_EQ(scene.transform(entity)->position.x, 0.0f);
}

