  EXPECT_TRUE(service.targets().empty());
  ASSERT_NE(scene.transform(parent), nullptr);
  EXPECT_FLOAT_EQ(scene.transform(parent)->position.x, 4.0f);
  ASSERT_NE(session.history().undo_label(), nullptr);
