TEST(ModelingSessionServiceTests,
     PreviewActionsExposeOnlyActiveToolSettingsAndLiveUpdate) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);
  const std::uint64_t initial_settings_revision =
      service.tool_settings_revision();
  EXPECT_EQ(service.tool_settings_revision(), initial_settings_revision);
  EXPECT_FALSE(service.operation_preview_active());

  const ModelingCreateBoxResult box = service.create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f}, .max = {1.0f, 1.0f, 1.0f}},
      .name = "Bevel Preview Box",
  });
  ASSERT_TRUE(box.ok) << box.message;
  ASSERT_TRUE(service.set_selection_mode(ModelingSelectionMode::Edge).ok);
  ASSERT_TRUE(seed_component_bulk_selection_scope(
                  service, box.object.modeling_object_id,
                  ModelingSelectionMode::Edge)
                  .ok);
  ASSERT_TRUE(service.select_all().ok);

  const ModelingCommandResult begin =
      service.execute_context_action("bevel_edges");
  ASSERT_TRUE(begin.ok) << begin.message;
  const std::uint64_t preview_settings_revision =
      service.tool_settings_revision();
  EXPECT_GT(preview_settings_revision, initial_settings_revision);
  EXPECT_EQ(service.tool_settings_revision(), preview_settings_revision);

  ModelingToolSettingsTarget target = service.tool_settings_target();
  EXPECT_TRUE(target.active);
  EXPECT_TRUE(target.operation_preview_active);
  EXPECT_TRUE(service.operation_preview_active());
  EXPECT_EQ(target.kind, ModelingToolSettingsTargetKind::EdgeBevel);
  EXPECT_EQ(target.action_id, "bevel_edges");
  EXPECT_EQ(target.operation_id, "edge_bevel");
  EXPECT_EQ(target.label, "Bevel Edges");

  const std::optional<MeshAsset> preview_before =
      service.compile_object_mesh(box.object.modeling_object_id);
  ASSERT_TRUE(preview_before.has_value());

  ModelingInteractionSettings settings = service.interaction_settings();
  settings.edge_bevel_width = 0.25;
  const ModelingCommandResult update =
      service.set_interaction_settings(settings);
  EXPECT_TRUE(update.ok) << update.message;
  EXPECT_TRUE(update.changed);
  const std::uint64_t updated_settings_revision =
      service.tool_settings_revision();
  EXPECT_GT(updated_settings_revision, preview_settings_revision);

  const std::optional<MeshAsset> preview_after =
      service.compile_object_mesh(box.object.modeling_object_id);
  ASSERT_TRUE(preview_after.has_value());
  EXPECT_NE(mesh_position_fingerprint(*preview_after),
            mesh_position_fingerprint(*preview_before));

  const ModelingCommandResult cancel =
      service.cancel_active_operation_preview();
  EXPECT_TRUE(cancel.ok) << cancel.message;
  EXPECT_FALSE(service.tool_settings_target().active);
  EXPECT_FALSE(service.operation_preview_active());
  EXPECT_GT(service.tool_settings_revision(), updated_settings_revision);
}

TEST(ModelingSessionServiceTests,
     HalfCutPreviewSettingFailuresKeepThePreviouslyCommittedSettings) {
  for (const bool rebuild_participants : {false, true}) {
    SCOPED_TRACE(rebuild_participants ? "structural rebuild"
                                      : "in-place update");
    SceneDocument scene;
    AssetRegistry assets;
    ModelingSessionService service(scene, assets);
    const ModelingCreateBoxResult box = service.create_box_from_bounds({
        .bounds = {.min = {-1.0f, -1.0f, -1.0f},
                   .max = {1.0f, 1.0f, 1.0f}},
        .name = "Half-Cut Failed Settings Box",
    });
    ASSERT_TRUE(box.ok) << box.message;
    const ModelingCommandResult begun =
        service.execute_context_action("half_cut");
    ASSERT_TRUE(begun.ok) << begun.message;

    const ModelingInteractionSettings previous =
        service.interaction_settings();
    const std::uint64_t previous_settings_revision =
        service.tool_settings_revision();
    const std::optional<MeshAsset> preview_before =
        service.compile_object_mesh(box.object.modeling_object_id);
    ASSERT_TRUE(preview_before.has_value());
    ModelingInteractionSettings candidate = previous;
    if (rebuild_participants) {
      candidate.half_cut_separate_parts = true;
    } else {
      candidate.half_cut_axis = ModelingHalfCutAxis::Z;
    }

    service.set_modeling_sdk_projection_failure_for_tests(
        ModelingSdkProjectionFailurePoint::AfterSdkMutation);
    const ModelingCommandResult failed =
        service.set_interaction_settings(candidate);
    EXPECT_FALSE(failed.ok);
    EXPECT_FALSE(failed.changed);
    EXPECT_NE(failed.message.find(rebuild_participants
                                      ? "Half-Cut preview rebuild failed."
                                      : "Half-Cut preview publication failed."),
              std::string::npos)
        << failed.message;
    EXPECT_EQ(service.interaction_settings(), previous);
    EXPECT_EQ(service.tool_settings_revision(), previous_settings_revision);
    EXPECT_TRUE(service.operation_preview_active());
    const std::optional<MeshAsset> preview_after =
        service.compile_object_mesh(box.object.modeling_object_id);
    ASSERT_TRUE(preview_after.has_value());
    EXPECT_EQ(mesh_position_fingerprint(*preview_after),
              mesh_position_fingerprint(*preview_before));
    service.set_modeling_sdk_projection_failure_for_tests(
        ModelingSdkProjectionFailurePoint::None);
    const ModelingCommandResult canceled =
        service.cancel_active_operation_preview();
    EXPECT_TRUE(canceled.ok) << canceled.message;
  }
}

TEST(ModelingSessionServiceTests,
     HalfCutPreviewResetFailuresPreserveSettingsAndAllowRetry) {
  for (const bool rebuild_participants : {false, true}) {
    SCOPED_TRACE(rebuild_participants ? "structural rebuild"
                                      : "in-place update");
    SceneDocument scene;
    AssetRegistry assets;
    ModelingSessionService service(scene, assets);
    const ModelingCreateBoxResult box = service.create_box_from_bounds({
        .bounds = {.min = {-1.0f, -1.0f, -1.0f},
                   .max = {1.0f, 1.0f, 1.0f}},
        .name = "Half-Cut Failed Reset Box",
    });
    ASSERT_TRUE(box.ok) << box.message;
    const ModelingCommandResult begun =
        service.execute_context_action("half_cut");
    ASSERT_TRUE(begun.ok) << begun.message;
    const ModelingInteractionSettings defaults = service.interaction_settings();
    ModelingInteractionSettings edited = defaults;
    edited.half_cut_axis = ModelingHalfCutAxis::Z;
    edited.half_cut_separate_parts = rebuild_participants;
    const ModelingCommandResult updated = service.set_interaction_settings(edited);
    ASSERT_TRUE(updated.ok) << updated.message;
    ASSERT_TRUE(updated.changed);
    const ModelingInteractionSettings accepted = service.interaction_settings();
    const std::uint64_t accepted_revision = service.tool_settings_revision();
    const std::optional<MeshAsset> accepted_mesh =
        service.compile_object_mesh(box.object.modeling_object_id);
    ASSERT_TRUE(accepted_mesh.has_value());

    service.set_modeling_sdk_projection_failure_for_tests(
        ModelingSdkProjectionFailurePoint::AfterSdkMutation);
    const ModelingCommandResult failed = service.reset_active_tool_settings();
    EXPECT_FALSE(failed.ok);
    EXPECT_FALSE(failed.changed);
    EXPECT_EQ(service.interaction_settings(), accepted);
    EXPECT_EQ(service.tool_settings_revision(), accepted_revision);
    EXPECT_TRUE(service.operation_preview_active());
    const std::optional<MeshAsset> after_failure =
        service.compile_object_mesh(box.object.modeling_object_id);
    ASSERT_TRUE(after_failure.has_value());
    EXPECT_EQ(mesh_position_fingerprint(*after_failure),
              mesh_position_fingerprint(*accepted_mesh));

    service.set_modeling_sdk_projection_failure_for_tests(
        ModelingSdkProjectionFailurePoint::None);
    const ModelingCommandResult retried = service.reset_active_tool_settings();
    ASSERT_TRUE(retried.ok) << retried.message;
    EXPECT_TRUE(retried.changed);
    EXPECT_EQ(service.interaction_settings(), defaults);
    EXPECT_GT(service.tool_settings_revision(), accepted_revision);
    const std::optional<MeshAsset> reset_mesh =
        service.compile_object_mesh(box.object.modeling_object_id);
    ASSERT_TRUE(reset_mesh.has_value());
    EXPECT_NE(mesh_position_fingerprint(*reset_mesh),
              mesh_position_fingerprint(*accepted_mesh));
    EXPECT_FALSE(service.reset_active_tool_settings().changed);
    EXPECT_TRUE(service.cancel_active_operation_preview().ok);
  }
}

