TEST(ModelingSelectionServiceTests,
     MarqueeFactsRetainExactDocumentsAndReleaseReplacedGeometry) {
  ModelingSelectionService service;
  quader_poly::Document document;
  const auto lower_left =
      quader_poly::add_vertex(document, {-1.0f, -1.0f, 0.0f});
  const auto lower_right =
      quader_poly::add_vertex(document, {1.0f, -1.0f, 0.0f});
  const auto upper_right =
      quader_poly::add_vertex(document, {1.0f, 1.0f, 0.0f});
  const auto upper_left =
      quader_poly::add_vertex(document, {-1.0f, 1.0f, 0.0f});
  (void)quader_poly::add_face(
      document, std::array{lower_left, lower_right, upper_right, upper_left},
      0u);
  std::vector<quader_editor_core::PolygonObject> objects{
      {.id = 11, .document = std::move(document)}};
  objects.push_back(objects.front());
  objects.back().id = 12;
  const std::weak_ptr<const quader_poly::Document> original_document =
      objects.front().document.topology_payload();
  ModelingBoxSelectRequest request{
      .camera = test_orthographic_viewport_camera(),
      .start = {0.0f, 0.0f},
      .end = {100.0f, 100.0f},
      .select_backfaces = false,
  };
  const auto project = [&] {
    return service.rectangle_projected_hits_request(
        objects, {}, quader_editor_core::SelectionMode::Face, request);
  };
  const auto first = project();
  ASSERT_EQ(first.faces.size(), 2u);
  EXPECT_TRUE(first.faces.front().front_facing);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 1u);
  EXPECT_EQ(service.rectangle_pick_facts_reuse_count(), 1u);

  // Participant identity, selection, camera and component mode do not alter
  // the shared document's incidence or authored-facing facts.
  objects.front().selected = true;
  objects.front().id = 21;
  request.camera.origin.x += 3.0f;
  request.select_backfaces = true;
  const auto vertices = service.rectangle_projected_hits_request(
      objects, {}, quader_editor_core::SelectionMode::Vertex, request);
  ASSERT_EQ(vertices.vertices.size(), 8u);
  EXPECT_EQ(vertices.vertices.front().object_id, 21);
  EXPECT_TRUE(vertices.vertices.front().front_facing);
  const auto edges = service.rectangle_projected_hits_request(
      objects, {}, quader_editor_core::SelectionMode::Edge, request);
  EXPECT_EQ(edges.edges.size(), 8u);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 1u);
  EXPECT_EQ(service.rectangle_pick_facts_reuse_count(), 5u);

  // A position edit detaches the document even when counts and IDs match.
  for (auto &vertex : objects.front().document.edit().vertices) {
    vertex.position.x += 4.0f;
  }
  const auto moved = project();
  ASSERT_EQ(moved.faces.size(), 2u);
  EXPECT_NEAR(moved.faces.front().screen_position.x -
                  moved.faces.back().screen_position.x,
              4.0f, 0.001f);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 2u);
  EXPECT_FALSE(original_document.expired());
  objects.back().document = objects.front().document;
  (void)project();
  // The earlier edge-mode query also pinned this source in the existing edge
  // cache. Its outer participant refresh/invalidation owns that separate pin.
  EXPECT_FALSE(original_document.expired());
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 2u);

  // Equal-size topology replacement changes facing and must not borrow the
  // old Face pointers retained by DocumentPickQuery.
  const std::weak_ptr<const quader_poly::Document> moved_document =
      objects.front().document.topology_payload();
  auto &face_vertices = objects.front().document.edit().faces.front().vertices;
  std::reverse(face_vertices.begin(), face_vertices.end());
  objects.back().document = objects.front().document;
  const auto reversed = project();
  ASSERT_EQ(reversed.faces.size(), 2u);
  EXPECT_FALSE(reversed.faces.front().front_facing);
  EXPECT_FALSE(reversed.faces.back().front_facing);
  EXPECT_TRUE(moved_document.expired());
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 3u);

  objects.front().document.edit().faces.front().material_slot = 7u;
  objects.back().document = objects.front().document;
  const auto reassigned = project();
  EXPECT_FALSE(reassigned.faces.front().front_facing);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 4u);
  service.invalidate_picking_cache();
  EXPECT_TRUE(original_document.expired());
  const auto rebuilt = project();
  EXPECT_FALSE(rebuilt.faces.front().front_facing);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 5u);

  const std::weak_ptr<const quader_poly::Document> removed_document =
      objects.front().document.topology_payload();
  objects.clear();
  EXPECT_FALSE(removed_document.expired());
  EXPECT_TRUE(project().faces.empty());
  EXPECT_TRUE(removed_document.expired());
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), 5u);
}

TEST(ModelingSessionServiceTests,
     RepeatedBoxSelectionDoesNotReprojectStableMeshGeometry) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);

  quader_poly::CubePrimitiveSpec dense_cube;
  dense_cube.width = 2.0f;
  dense_cube.height = 2.0f;
  dense_cube.depth = 2.0f;
  dense_cube.width_segments = 24;
  dense_cube.height_segments = 24;
  dense_cube.depth_segments = 24;
  const ModelingCreateBoxResult mesh = service.create_mesh({
      .document = quader_poly::make_cube(dense_cube),
      .name = "Repeated Box Selection Dense Cube",
  });
  ASSERT_TRUE(mesh.ok) << mesh.message;
  ASSERT_TRUE(service.set_selection_mode(ModelingSelectionMode::Face).ok);
  ASSERT_TRUE(service.clear_selection().ok);

  const ModelingSelectionBoxBaseline baseline =
      service.capture_box_selection_baseline();
  ModelingBoxSelectRequest request{
      .camera = test_orthographic_viewport_camera(),
      .start = {35.0f, 35.0f},
      .end = {65.0f, 65.0f},
      .edit = ModelingSelectionEdit::Replace,
      .rule = ModelingBoxSelectionRule::Crossing,
  };
  const std::uint64_t builds_before =
      service.transformed_picking_projection_build_count();
  const std::uint64_t rectangle_builds_before =
      service.rectangle_picking_projection_build_count();
  const std::uint64_t universe_builds_before =
      service.rectangle_selection_universe_build_count();
  const std::uint64_t resolutions_before =
      service.rectangle_selection_resolution_build_count();
  const std::uint64_t facts_before = service.rectangle_pick_facts_build_count();
  const ModelingSelectionSummary first = service.box_select(request, baseline);
  ASSERT_GT(first.selected_face_count, 0u);
  const std::uint64_t builds_after_first =
      service.transformed_picking_projection_build_count();
  EXPECT_EQ(builds_after_first, builds_before + 1u);
  const std::uint64_t rectangle_builds_after_first =
      service.rectangle_picking_projection_build_count();
  const std::uint64_t universe_builds_after_first =
      service.rectangle_selection_universe_build_count();
  const std::uint64_t resolutions_after_first =
      service.rectangle_selection_resolution_build_count();
  EXPECT_EQ(rectangle_builds_after_first, rectangle_builds_before + 1u);
  EXPECT_EQ(universe_builds_after_first, universe_builds_before + 1u);
  EXPECT_EQ(resolutions_after_first, resolutions_before + 1u);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 1u);

  for (int sample = 0; sample < 32; ++sample) {
    request.end.x = 65.0f + static_cast<float>(sample) * 0.01f;
    const ModelingSelectionSummary repeated =
        service.box_select(request, baseline);
    EXPECT_EQ(repeated.selected_face_count, first.selected_face_count);
  }
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            builds_after_first);
  EXPECT_EQ(service.rectangle_picking_projection_build_count(),
            rectangle_builds_after_first);
  EXPECT_EQ(service.rectangle_selection_universe_build_count(),
            universe_builds_after_first);
  EXPECT_EQ(service.rectangle_selection_resolution_build_count(),
            resolutions_after_first);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 1u);

  request.camera.orthographic_size += 1.0;
  (void)service.box_select(request, baseline);
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            builds_after_first);
  EXPECT_EQ(service.rectangle_picking_projection_build_count(),
            rectangle_builds_after_first + 1u);
  EXPECT_EQ(service.rectangle_selection_universe_build_count(),
            universe_builds_after_first);
  EXPECT_EQ(service.rectangle_selection_resolution_build_count(),
            resolutions_after_first + 1u);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 1u);
  EXPECT_EQ(service.rectangle_pick_facts_reuse_count(), 1u);

  ASSERT_TRUE(scene.set_selectable(mesh.object.entity, false));
  const ModelingSelectionSummary unselectable =
      service.box_select(request, baseline);
  EXPECT_EQ(unselectable.selected_face_count, 0u);
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            builds_after_first + 1u);
  EXPECT_EQ(service.rectangle_picking_projection_build_count(),
            rectangle_builds_after_first + 2u);
  EXPECT_EQ(service.rectangle_selection_universe_build_count(),
            universe_builds_after_first + 1u);
  EXPECT_EQ(service.rectangle_selection_resolution_build_count(),
            resolutions_after_first + 2u);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 1u);

  ASSERT_TRUE(scene.set_selectable(mesh.object.entity, true));
  EXPECT_EQ(service.box_select(request, baseline).selected_face_count,
            first.selected_face_count);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 2u);
  ASSERT_TRUE(scene.set_visible(mesh.object.entity, false));
  EXPECT_EQ(service.box_select(request, baseline).selected_face_count, 0u);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 2u);
  ASSERT_TRUE(scene.set_visible(mesh.object.entity, true));
  EXPECT_EQ(service.box_select(request, baseline).selected_face_count,
            first.selected_face_count);
  EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 3u);
}

TEST(ModelingSessionServiceTests,
     BoxBackfacePolicyUsesAuthoredWindingThroughReflectedTinyTransform) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);

  quader_poly::Document document;
  const quader_poly::ElementId v0 =
      quader_poly::add_vertex(document, {-1.0f, -1.0f, 0.0f});
  const quader_poly::ElementId v1 =
      quader_poly::add_vertex(document, {1.0f, -1.0f, 0.0f});
  const quader_poly::ElementId v2 =
      quader_poly::add_vertex(document, {1.0f, 1.0f, 0.0f});
  const quader_poly::ElementId v3 =
      quader_poly::add_vertex(document, {-1.0f, 1.0f, 0.0f});
  [[maybe_unused]] const quader_poly::ElementId loose_vertex =
      quader_poly::add_vertex(document, {0.0f, 0.0f, 0.0f});
  [[maybe_unused]] const quader_poly::ElementId face =
      quader_poly::add_face(document, std::array{v0, v1, v2, v3}, 0U);
  const ModelingCreateBoxResult mesh = service.create_mesh({
      .document = std::move(document),
      .name = "Reflected Box Backface Source",
  });
  ASSERT_TRUE(mesh.ok) << mesh.message;

  TransformComponent transform;
  ModelingBoxSelectRequest request{
      .camera = test_orthographic_viewport_camera(),
      .start = {49.0f, 49.0f},
      .end = {51.0f, 51.0f},
      .edit = ModelingSelectionEdit::Replace,
      .rule = ModelingBoxSelectionRule::Contain,
      .select_backfaces = false,
  };
  struct ModeExpectation {
    ModelingSelectionMode mode;
    std::size_t front_count;
    std::size_t reflected_front_only_count;
    std::size_t reflected_two_sided_count;
  };
  const std::array expectations{
      ModeExpectation{ModelingSelectionMode::Face, 1U, 0U, 1U},
      ModeExpectation{ModelingSelectionMode::Edge, 4U, 0U, 4U},
      ModeExpectation{ModelingSelectionMode::Vertex, 5U, 1U, 5U},
  };
  const auto selected_count = [](const ModelingSelectionSummary &summary,
                                 ModelingSelectionMode mode) -> std::size_t {
    switch (mode) {
    case ModelingSelectionMode::Face:
      return summary.selected_face_count;
    case ModelingSelectionMode::Edge:
      return summary.selected_edge_count;
    case ModelingSelectionMode::Vertex:
      return summary.selected_vertex_count;
    default:
      return std::size_t{0U};
    }
  };
  const std::uint64_t facts_before = service.rectangle_pick_facts_build_count();

  for (const ModeExpectation &expectation : expectations) {
    ASSERT_TRUE(service.set_selection_mode(expectation.mode).ok);
    transform.scale = {0.001f, 0.002f, 0.004f};
    ASSERT_TRUE(scene.set_transform(mesh.object.entity, transform));
    request.select_backfaces = false;
    EXPECT_EQ(selected_count(service.box_select(request), expectation.mode),
              expectation.front_count);

    transform.scale.x = -0.001f;
    ASSERT_TRUE(scene.set_transform(mesh.object.entity, transform));
    EXPECT_EQ(selected_count(service.box_select(request), expectation.mode),
              expectation.reflected_front_only_count);
    const std::uint64_t front_only_projection_builds =
        service.rectangle_picking_projection_build_count();

    request.select_backfaces = true;
    EXPECT_EQ(selected_count(service.box_select(request), expectation.mode),
              expectation.reflected_two_sided_count);
    EXPECT_EQ(service.rectangle_picking_projection_build_count(),
              front_only_projection_builds);
    EXPECT_EQ(service.rectangle_pick_facts_build_count(), facts_before + 2u);
  }
}

TEST(ModelingSessionServiceTests,
     MeshVertexSnapTargetUsesWorldPickingAndOmitsMovingSelection) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);

  const ModelingCreateBoxResult box = service.create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f},
                 .max = {1.0f, 1.0f, 1.0f}},
      .name = "Vertex Snap Target",
  });
  ASSERT_TRUE(box.ok) << box.message;
  TransformComponent transform = *scene.transform(box.object.entity);
  transform.position = {3.0f, 0.0f, 0.0f};
  ASSERT_TRUE(scene.set_transform(box.object.entity, transform));
  ASSERT_TRUE(service
                  .set_object_selection(std::span<const EntityId>{},
                                        kInvalidEntityId)
                  .ok);

  const ModelingRay ray{
      .origin = {4.0f, 1.0f, 5.0f},
      .direction = {0.0f, 0.0f, -1.0f},
  };
  const std::optional<ModelingMeshVertexSnapTarget> target =
      service.pick_mesh_vertex_snap_target(ray, 0.3);
  ASSERT_TRUE(target.has_value());
  EXPECT_EQ(target->modeling_object_id, box.object.modeling_object_id);
  EXPECT_NE(target->vertex_id, quader_poly::kInvalidElementId);
  expect_vec3_near(target->world_position, {4.0f, 1.0f, 1.0f});
  EXPECT_NEAR(target->ray_distance, 4.0, 0.001);
  EXPECT_NEAR(target->pick_distance, 0.0, 0.001);

  const std::array selected{box.object.entity};
  ASSERT_TRUE(service.set_object_selection(selected, box.object.entity).ok);
  EXPECT_FALSE(service.pick_mesh_vertex_snap_target(ray, 0.3).has_value());
  EXPECT_TRUE(
      service.pick_mesh_vertex_snap_target(ray, 0.3, false).has_value());
  EXPECT_FALSE(service.pick_mesh_vertex_snap_target(ray, 0.0).has_value());
}

TEST(ModelingSessionServiceTests,
     LayerLockRevisionInvalidatesWarmPointAndRectanglePickingCaches) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);

  const ModelingCreateBoxResult mesh = service.create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f},
                 .max = {1.0f, 1.0f, 1.0f}},
      .name = "Layer Lock Picking Box",
  });
  ASSERT_TRUE(mesh.ok) << mesh.message;
  const SceneLayerId layer = scene.create_layer("Picking Layer");
  ASSERT_NE(layer, kInvalidSceneLayerId);
  ASSERT_TRUE(scene.set_entity_layer(mesh.object.entity, layer));

  const ModelingPickSelectRequest point_request{
      .ray = {.origin = {0.0f, 0.0f, 5.0f},
              .direction = {0.0f, 0.0f, -1.0f}},
  };
  const ModelingBoxSelectRequest rectangle_request{
      .camera = test_orthographic_viewport_camera(),
      .start = {35.0f, 35.0f},
      .end = {65.0f, 65.0f},
      .edit = ModelingSelectionEdit::Replace,
      .rule = ModelingBoxSelectionRule::Contain,
  };

  const std::optional<EntityId> warm_point =
      service.pick_object_entity(point_request);
  ASSERT_TRUE(warm_point.has_value());
  EXPECT_EQ(*warm_point, mesh.object.entity);
  const ModelingSelectionSummary warm_rectangle =
      service.box_select(rectangle_request);
  ASSERT_EQ(warm_rectangle.selected_object_count, 1u);
  const std::uint64_t point_builds =
      service.transformed_picking_projection_build_count();
  const std::uint64_t rectangle_builds =
      service.rectangle_picking_projection_build_count();

  ASSERT_TRUE(scene.set_layer_locked(layer, true));
  EXPECT_FALSE(service.pick_object_entity(point_request).has_value());
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            point_builds + 1u);
  const ModelingSelectionSummary locked_rectangle =
      service.box_select(rectangle_request);
  EXPECT_EQ(locked_rectangle.selected_object_count, 0u);
  EXPECT_EQ(service.rectangle_picking_projection_build_count(),
            rectangle_builds + 1u);

  ASSERT_TRUE(scene.set_layer_locked(layer, false));
  const std::optional<EntityId> unlocked_point =
      service.pick_object_entity(point_request);
  ASSERT_TRUE(unlocked_point.has_value());
  EXPECT_EQ(*unlocked_point, mesh.object.entity);
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            point_builds + 2u);
  const ModelingSelectionSummary unlocked_rectangle =
      service.box_select(rectangle_request);
  EXPECT_EQ(unlocked_rectangle.selected_object_count, 1u);
  EXPECT_EQ(service.rectangle_picking_projection_build_count(),
            rectangle_builds + 2u);
}

