TEST(ModelingSessionServiceTests,
     InstanceOccurrenceChangesInvalidateWarmPickingParticipationCaches) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);

  const ModelingCreateBoxResult member = service.create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f},
                 .max = {1.0f, 1.0f, 1.0f}},
      .name = "Instance Picking Member",
  });
  ASSERT_TRUE(member.ok) << member.message;
  const EntityId definition = scene.create_empty("Picking Definition");
  ASSERT_NE(definition, kInvalidEntityId);
  ASSERT_TRUE(scene.set_instance_definition(definition));
  ASSERT_TRUE(scene.set_parent(member.object.entity, definition, false));
  const EntityId occurrence = scene.create_empty("Future Occurrence");
  ASSERT_NE(occurrence, kInvalidEntityId);

  const ModelingPickSelectRequest point_request{
      .ray = {.origin = {0.0f, 0.0f, 5.0f},
              .direction = {0.0f, 0.0f, -1.0f}},
  };
  const ModelingBoxSelectRequest rectangle_request{
      .camera = test_orthographic_viewport_camera(),
      .start = {35.0f, 35.0f},
      .end = {65.0f, 65.0f},
      .edit = ModelingSelectionEdit::Replace,
      .rule = ModelingBoxSelectionRule::Contain,
  };

  EXPECT_FALSE(service.pick_object_entity(point_request).has_value());
  EXPECT_TRUE(service.box_pick_object_entities(rectangle_request).empty());
  const std::uint64_t point_builds =
      service.transformed_picking_projection_build_count();
  const std::uint64_t rectangle_builds =
      service.rectangle_picking_projection_build_count();

  ASSERT_TRUE(scene.set_instance_occurrence(
      occurrence, InstanceOccurrenceComponent{.definition = definition}));
  const std::optional<EntityId> occurrence_hit =
      service.pick_object_entity(point_request);
  ASSERT_TRUE(occurrence_hit.has_value());
  EXPECT_EQ(*occurrence_hit, occurrence);
  EXPECT_EQ(service.box_pick_object_entities(rectangle_request),
            (std::vector<EntityId>{occurrence}));
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            point_builds + 1u);
  EXPECT_EQ(service.rectangle_picking_projection_build_count(),
            rectangle_builds + 1u);

  ASSERT_TRUE(scene.clear_instance_occurrence(occurrence));
  EXPECT_FALSE(service.pick_object_entity(point_request).has_value());
  EXPECT_TRUE(service.box_pick_object_entities(rectangle_request).empty());
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            point_builds + 2u);
  EXPECT_EQ(service.rectangle_picking_projection_build_count(),
            rectangle_builds + 2u);
}

TEST(ModelingSessionServiceTests,
     TwoHundredSharedDuplicatesBuildOneLocalPickingGeometryAndTransformWithoutRebuild) {
  SceneDocument scene;
  AssetRegistry assets;
  EditorHistoryService history;
  DocumentCommandService document_commands(scene, history);
  ModelingSessionService service(scene, assets);
  SceneStructuralLifecycleService structural_lifecycle(
      scene, history, document_commands, service);

  const ModelingCreateBoxResult source = service.create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f},
                 .max = {1.0f, 1.0f, 1.0f}},
      .name = "Shared Picking Box",
  });
  ASSERT_TRUE(source.ok) << source.message;
  std::vector<EntityId> participants{source.object.entity};
  participants.reserve(200u);
  for (std::size_t index = 1u; index < 200u; ++index) {
    const SceneStructuralDuplicateResult duplicated =
        structural_lifecycle.duplicate_selected_hierarchy(
            ModelingSelectionMode::Object);
    ASSERT_TRUE(duplicated.ok) << duplicated.message;
    ASSERT_TRUE(duplicated.changed);
    const EntityId duplicate = scene.primary_selection();
    ASSERT_NE(duplicate, kInvalidEntityId);
    TransformComponent transform;
    transform.position = {static_cast<float>(index) * 3.0f, 0.0f, 0.0f};
    scene.set_transform(duplicate, transform);
    participants.push_back(duplicate);
  }
  ASSERT_EQ(service.objects().size(), 200u);

  const std::uint64_t geometry_builds_before =
      service.local_face_geometry_build_count();
  const std::uint64_t projection_builds_before =
      service.transformed_picking_projection_build_count();
  const std::uint64_t world_bounds_builds_before =
      service.world_pick_bounds_build_count();
  const float last_x = 3.0f * 199.0f;
  const std::optional<EntityId> first_hit =
      service.pick_object_entity(ModelingPickSelectRequest{
          .ray = {.origin = {last_x, 0.0f, 5.0f},
                  .direction = {0.0f, 0.0f, -1.0f}},
      });
  ASSERT_TRUE(first_hit.has_value());
  EXPECT_EQ(*first_hit, participants.back());
  EXPECT_EQ(service.local_face_geometry_build_count(),
            geometry_builds_before + 1u);
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            projection_builds_before + 1u);
  EXPECT_EQ(service.world_pick_bounds_build_count(),
            world_bounds_builds_before + participants.size());

  TransformComponent moved = *scene.transform(participants.back());
  moved.position.x = 700.0f;
  scene.set_transform(participants.back(), moved);
  const std::optional<EntityId> moved_hit =
      service.pick_object_entity(ModelingPickSelectRequest{
          .ray = {.origin = {700.0f, 0.0f, 5.0f},
                  .direction = {0.0f, 0.0f, -1.0f}},
      });
  ASSERT_TRUE(moved_hit.has_value());
  EXPECT_EQ(*moved_hit, participants.back());
  EXPECT_EQ(service.local_face_geometry_build_count(),
            geometry_builds_before + 1u);
  EXPECT_EQ(service.transformed_picking_projection_build_count(),
            projection_builds_before + 2u);
  EXPECT_EQ(service.world_pick_bounds_build_count(),
            world_bounds_builds_before + participants.size() + 1u);
}

TEST(ModelingSessionServiceTests,
     ContextActionsExposeFacePanelAndKeepBridgeDisabledForOneFace) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);

  const ModelingCreateBoxResult box = service.create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f}, .max = {1.0f, 1.0f, 1.0f}},
      .name = "Face Action Box",
  });
  ASSERT_TRUE(box.ok) << box.message;
  ASSERT_TRUE(service.set_selection_mode(ModelingSelectionMode::Face).ok);

  const ModelingSelectionSummary picked =
      service.pick_select(ModelingPickSelectRequest{
          .ray = {.origin = {0.0f, 0.0f, 5.0f},
                  .direction = {0.0f, 0.0f, -1.0f}},
          .click_count = 1,
      });
  ASSERT_EQ(picked.selected_face_count, 1u);

  const ModelingActionSet actions = service.context_action_set({
      .surface = ModelingActionSurface::OperationsPanel,
      .include_disabled = true,
  });
  const ModelingSdkProjectionStats first_action_query =
      service.modeling_sdk_projection_stats_for_tests();
  EXPECT_GT(first_action_query.selection_topology_build_count, 0U);
  for (int frame = 0; frame < 32; ++frame) {
    (void)service.context_action_set({
        .surface = ModelingActionSurface::OperationsPanel,
        .include_disabled = true,
    });
  }
  const ModelingSdkProjectionStats repeated_action_queries =
      service.modeling_sdk_projection_stats_for_tests();
  EXPECT_EQ(repeated_action_queries.selection_topology_build_count,
            first_action_query.selection_topology_build_count);
  ASSERT_EQ(actions.panels.size(), 1u);
  EXPECT_EQ(find_action_panel(actions, "object_operations"), nullptr);
  EXPECT_EQ(find_action_panel(actions, "edge_operations"), nullptr);

  const ModelingActionPanel *face_panel =
      find_action_panel(actions, "face_operations");
  ASSERT_NE(face_panel, nullptr);
  EXPECT_EQ(face_panel->selection_mode_id, "face");
  EXPECT_EQ(face_panel->visibility, ModelingActionVisibility::Enabled);

  const ModelingActionItem *invert =
      find_action_item(*face_panel, "invert_faces");
  ASSERT_NE(invert, nullptr);
  EXPECT_EQ(invert->operation_id, "flip_face_normals");
  EXPECT_EQ(invert->visibility, ModelingActionVisibility::Enabled);

  const ModelingActionItem *bridge =
      find_action_item(*face_panel, "bridge_faces");
  ASSERT_NE(bridge, nullptr);
  EXPECT_EQ(bridge->operation_id, "bridge");
  EXPECT_EQ(bridge->visibility, ModelingActionVisibility::Disabled);

  const ModelingActionItem *interpolated_bridge =
      find_action_item(*face_panel, "interpolated_bridge_faces");
  ASSERT_NE(interpolated_bridge, nullptr);
  EXPECT_EQ(interpolated_bridge->operation_id, "bridge");
  EXPECT_EQ(interpolated_bridge->preview_kind,
            ModelingActionPreviewKind::Bridge);

  const ModelingCommandResult executed =
      service.execute_context_action("invert_faces");
  EXPECT_TRUE(executed.ok) << executed.message;
}

TEST(
    ModelingSessionServiceTests,
    RmbMeshPickWithExistingFaceSelectionPreservesSelectionAndAllowsContextMenu) {
  SceneDocument scene;
  AssetRegistry assets;
  ModelingSessionService service(scene, assets);

  const ModelingCreateBoxResult box = service.create_box_from_bounds({
      .bounds = {.min = {-1.0f, -1.0f, -1.0f}, .max = {1.0f, 1.0f, 1.0f}},
      .name = "RMB Face Context Box",
  });
  ASSERT_TRUE(box.ok) << box.message;
  ASSERT_TRUE(service.set_selection_mode(ModelingSelectionMode::Face).ok);

  const ModelingSelectionSummary picked =
      service.pick_select(ModelingPickSelectRequest{
          .ray = {.origin = {0.0f, 0.0f, 5.0f},
                  .direction = {0.0f, 0.0f, -1.0f}},
          .click_count = 1,
      });
  ASSERT_TRUE(picked.has_selection);
  ASSERT_EQ(picked.selected_face_count, 1u);

  const ModelingSelectionSummary multi_picked =
      service.pick_select(ModelingPickSelectRequest{
          .ray = {.origin = {0.0f, 0.0f, -5.0f},
                  .direction = {0.0f, 0.0f, 1.0f}},
          .click_count = 1,
          .shift_pressed = true,
      });
  ASSERT_TRUE(multi_picked.has_selection);
  ASSERT_EQ(multi_picked.selected_face_count, 2u);
  const int active_object_before_context = multi_picked.active_object_id;
  const int active_face_before_context = multi_picked.active_face_id;

  const ModelingSelectionSummary rmb_on_unselected_with_existing_selection =
      service.pick_select(ModelingPickSelectRequest{
          .ray = {.origin = {5.0f, 0.0f, 0.0f},
                  .direction = {-1.0f, 0.0f, 0.0f}},
          .click_count = 1,
          .preserve_selection_on_miss = true,
          .preserve_selection_on_selected_hit = true,
          .preserve_existing_component_selection_on_hit = true,
      });
  ASSERT_TRUE(rmb_on_unselected_with_existing_selection.has_selection);
  EXPECT_EQ(rmb_on_unselected_with_existing_selection.active_object_id,
            active_object_before_context);
  EXPECT_EQ(rmb_on_unselected_with_existing_selection.active_face_id,
            active_face_before_context);
  EXPECT_EQ(rmb_on_unselected_with_existing_selection.selected_face_count, 2u);

  const ModelingSelectionSummary rmb_on_already_selected =
      service.pick_select(ModelingPickSelectRequest{
          .ray = {.origin = {0.0f, 0.0f, 5.0f},
                  .direction = {0.0f, 0.0f, -1.0f}},
          .click_count = 1,
          .preserve_selection_on_miss = true,
          .preserve_selection_on_selected_hit = true,
          .preserve_existing_component_selection_on_hit = true,
      });
  ASSERT_TRUE(rmb_on_already_selected.has_selection);
  EXPECT_EQ(rmb_on_already_selected.selected_face_count, 2u);

  ModelingActionQuery query;
  query.surface = ModelingActionSurface::ViewportContextMenu;
  query.include_disabled = true;
  const std::vector<ModelingActionItem> actions =
      service.context_actions(query);
  ASSERT_FALSE(actions.empty());

  EXPECT_TRUE(should_open_viewport_context_menu({
      .right_press_tracked = true,
      .right_released = true,
      .release_inside_viewport = true,
      .target_hit = rmb_on_already_selected.has_selection,
      .has_actions = !actions.empty(),
      .press_screen = {320.0f, 240.0f},
      .release_screen = {320.0f, 240.0f},
  }));

  const ModelingSelectionSummary missed_with_preserved_selection =
      service.pick_select(ModelingPickSelectRequest{
          .ray = {.origin = {8.0f, 8.0f, 5.0f},
                  .direction = {0.0f, 0.0f, -1.0f}},
          .click_count = 1,
          .preserve_selection_on_miss = true,
      });
  ASSERT_TRUE(missed_with_preserved_selection.has_selection);
  EXPECT_EQ(missed_with_preserved_selection.selected_face_count, 2u);
  EXPECT_TRUE(should_open_viewport_context_menu({
      .right_press_tracked = true,
      .right_released = true,
      .release_inside_viewport = true,
      .target_hit = missed_with_preserved_selection.has_selection,
      .has_actions = true,
      .press_screen = {100.0f, 100.0f},
      .release_screen = {100.0f, 100.0f},
  }));

  const ModelingSelectionSummary missed_without_preserving_selection =
      service.pick_select(ModelingPickSelectRequest{
          .ray = {.origin = {8.0f, 8.0f, 5.0f},
                  .direction = {0.0f, 0.0f, -1.0f}},
          .click_count = 1,
      });
  EXPECT_FALSE(missed_without_preserving_selection.has_selection);
}

